BEGIN;
CREATE TABLE IF NOT EXISTS public.training_test_authoritative_bank (
  test_id text PRIMARY KEY,
  training_id text NOT NULL,
  test_definition jsonb NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.training_test_authoritative_bank ENABLE ROW LEVEL SECURITY;
REVOKE ALL PRIVILEGES ON TABLE public.training_test_authoritative_bank FROM PUBLIC, anon, authenticated;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_working_at_heights','tr_working_at_heights','{"id":"test_working_at_heights","trainingId":"tr_working_at_heights","title":"Examen Trabajo en Altura","description":"Evaluación final del training Trabajo en Altura.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"wah_q01","question":"¿Cuál es el principal riesgo al trabajar en altura?","options":[{"key":"a","text":"Golpes de calor"},{"key":"b","text":"Caídas de personas"},{"key":"c","text":"Ruido excesivo"},{"key":"d","text":"Polvo"}],"correctOption":"b"},{"id":"wah_q02","question":"Antes de utilizar el equipo de protección contra caídas, se debe:","options":[{"key":"a","text":"Guardarlo"},{"key":"b","text":"Prestarlo a un compañero"},{"key":"c","text":"Inspeccionarlo"},{"key":"d","text":"Pintarlo"}],"correctOption":"c"},{"id":"wah_q03","question":"¿Qué debe verificarse durante la inspección del arnés?","options":[{"key":"a","text":"Color únicamente"},{"key":"b","text":"Etiquetas, costuras y estado general"},{"key":"c","text":"Marca comercial"},{"key":"d","text":"Antigüedad del usuario"}],"correctOption":"b"},{"id":"wah_q04","question":"Las herramientas y materiales deben asegurarse para:","options":[{"key":"a","text":"Evitar pérdidas económicas"},{"key":"b","text":"Facilitar el transporte"},{"key":"c","text":"Evitar caídas de objetos"},{"key":"d","text":"Reducir el peso"}],"correctOption":"c"},{"id":"wah_q05","question":"Si se trabaja fuera de una zona protegida, se debe:","options":[{"key":"a","text":"Trabajar más rápido"},{"key":"b","text":"Utilizar siempre puntos de anclaje autorizados"},{"key":"c","text":"Retirar el arnés"},{"key":"d","text":"Pedir ayuda solamente"}],"correctOption":"b"},{"id":"wah_q06","question":"Un punto de anclaje autorizado es:","options":[{"key":"a","text":"Cualquier estructura disponible"},{"key":"b","text":"Un elemento diseñado y aprobado para soportar cargas de caída"},{"key":"c","text":"Una baranda improvisada"},{"key":"d","text":"Una herramienta pesada"}],"correctOption":"b"},{"id":"wah_q07","question":"¿Cuándo debe inspeccionarse el equipo de protección contra caídas?","options":[{"key":"a","text":"Una vez al año"},{"key":"b","text":"Antes de cada uso"},{"key":"c","text":"Solo cuando parezca dañado"},{"key":"d","text":"Después del trabajo"}],"correctOption":"b"},{"id":"wah_q08","question":"¿Qué puede ocurrir si una herramienta no está asegurada?","options":[{"key":"a","text":"Nada"},{"key":"b","text":"Puede caer y lesionar a personas"},{"key":"c","text":"Mejora la productividad"},{"key":"d","text":"Reduce el riesgo"}],"correctOption":"b"},{"id":"wah_q09","question":"¿Cuál de las siguientes acciones es segura?","options":[{"key":"a","text":"Utilizar un anclaje no identificado"},{"key":"b","text":"Trabajar sin arnés"},{"key":"c","text":"Revisar el equipo antes de usarlo"},{"key":"d","text":"Lanzar herramientas al suelo"}],"correctOption":"c"},{"id":"wah_q10","question":"El uso correcto de los puntos de anclaje ayuda a:","options":[{"key":"a","text":"Reducir el riesgo de caídas"},{"key":"b","text":"Aumentar la velocidad de trabajo"},{"key":"c","text":"Evitar inspecciones"},{"key":"d","text":"Ahorrar equipos"}],"correctOption":"a"},{"id":"wah_q11","question":"¿Qué se debe hacer si el equipo presenta daños?","options":[{"key":"a","text":"Utilizarlo igualmente"},{"key":"b","text":"Repararlo de forma improvisada"},{"key":"c","text":"Retirarlo de servicio y reportarlo"},{"key":"d","text":"Ignorarlo"}],"correctOption":"c"},{"id":"wah_q12","question":"¿Quién es responsable de inspeccionar su equipo antes de usarlo?","options":[{"key":"a","text":"El supervisor únicamente"},{"key":"b","text":"El trabajador que lo utilizará"},{"key":"c","text":"El área administrativa"},{"key":"d","text":"El proveedor"}],"correctOption":"b"},{"id":"wah_q13","question":"¿Por qué es importante asegurar materiales y herramientas?","options":[{"key":"a","text":"Para mantener el orden únicamente"},{"key":"b","text":"Para evitar accidentes por caída de objetos"},{"key":"c","text":"Para ahorrar tiempo"},{"key":"d","text":"Para facilitar la limpieza"}],"correctOption":"b"},{"id":"wah_q14","question":"¿Qué elemento forma parte de la protección contra caídas?","options":[{"key":"a","text":"Arnés de seguridad"},{"key":"b","text":"Escoba"},{"key":"c","text":"Linterna"},{"key":"d","text":"Extintor"}],"correctOption":"a"},{"id":"wah_q15","question":"La conducta correcta al trabajar en altura es:","options":[{"key":"a","text":"Utilizar equipos inspeccionados y puntos de anclaje autorizados"},{"key":"b","text":"Confiar únicamente en la experiencia"},{"key":"c","text":"Trabajar sin protección en tareas breves"},{"key":"d","text":"Omitir revisiones para ahorrar tiempo"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_hand_safety','tr_hand_safety','{"id":"test_hand_safety","trainingId":"tr_hand_safety","title":"Examen Cuidado de Manos","description":"Evaluación final del training Cuidado de Manos. Este tema no forma parte del set de 9 reglas IOGP Life-Saving Rules; se recomienda validarlo contra el video usado como contenido.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"hs_q01","question":"¿Cuál es el objetivo principal del cuidado de manos?","options":[{"key":"a","text":"Prevenir atrapamientos, cortes, golpes, quemaduras y exposición a sustancias"},{"key":"b","text":"Trabajar más rápido"},{"key":"c","text":"Evitar completar permisos"},{"key":"d","text":"Usar siempre la misma herramienta"}],"correctOption":"a"},{"id":"hs_q02","question":"Antes de usar una herramienta manual, se debe:","options":[{"key":"a","text":"Verificar que esté en buen estado y sea adecuada para la tarea"},{"key":"b","text":"Elegir la más cercana"},{"key":"c","text":"Usarla aunque esté dañada"},{"key":"d","text":"Prestarla sin revisar"}],"correctOption":"a"},{"id":"hs_q03","question":"Un punto de pellizco o atrapamiento es:","options":[{"key":"a","text":"Un lugar donde la mano puede quedar atrapada entre partes móviles o cargas"},{"key":"b","text":"Una zona de descanso"},{"key":"c","text":"Una etiqueta de herramienta"},{"key":"d","text":"Un tipo de guante"}],"correctOption":"a"},{"id":"hs_q04","question":"Para proteger las manos, debo mantenerlas fuera de:","options":[{"key":"a","text":"Líneas de fuego, puntos de pellizco y partes móviles"},{"key":"b","text":"Zonas iluminadas"},{"key":"c","text":"Áreas señalizadas solamente"},{"key":"d","text":"Superficies limpias"}],"correctOption":"a"},{"id":"hs_q05","question":"Los guantes deben seleccionarse según:","options":[{"key":"a","text":"El riesgo de la tarea y el material manipulado"},{"key":"b","text":"El color preferido"},{"key":"c","text":"La talla de otro compañero"},{"key":"d","text":"Lo que esté más cerca"}],"correctOption":"a"},{"id":"hs_q06","question":"¿Qué acción es insegura?","options":[{"key":"a","text":"Usar la mano como guía cerca de una carga en movimiento"},{"key":"b","text":"Identificar puntos de atrapamiento"},{"key":"c","text":"Usar herramienta adecuada"},{"key":"d","text":"Inspeccionar guantes"}],"correctOption":"a"},{"id":"hs_q07","question":"Si una herramienta está dañada, corresponde:","options":[{"key":"a","text":"Retirarla de servicio y reportarla"},{"key":"b","text":"Usarla una vez más"},{"key":"c","text":"Repararla improvisadamente"},{"key":"d","text":"Prestársela a otro"}],"correctOption":"a"},{"id":"hs_q08","question":"Al manipular sustancias químicas, la protección de manos debe considerar:","options":[{"key":"a","text":"Compatibilidad del guante con la sustancia"},{"key":"b","text":"Solo el espesor visual"},{"key":"c","text":"Solo el precio del guante"},{"key":"d","text":"No usar guantes para sentir mejor"}],"correctOption":"a"},{"id":"hs_q09","question":"Antes de colocar las manos en un área de trabajo, se debe:","options":[{"key":"a","text":"Pensar dónde podrían moverse equipos, herramientas o materiales"},{"key":"b","text":"Actuar rápido"},{"key":"c","text":"Mirar solo el resultado final"},{"key":"d","text":"Pedir que otro revise después"}],"correctOption":"a"},{"id":"hs_q10","question":"Una postura segura de manos implica:","options":[{"key":"a","text":"Mantener dedos y manos alejados de bordes cortantes o partes móviles"},{"key":"b","text":"Sostener piezas desde puntos de atrapamiento"},{"key":"c","text":"Empujar con los dedos hacia una zona de corte"},{"key":"d","text":"Retirar protecciones de la máquina"}],"correctOption":"a"},{"id":"hs_q11","question":"Las protecciones o guardas de equipos sirven para:","options":[{"key":"a","text":"Evitar contacto con partes peligrosas"},{"key":"b","text":"Molestar al operador"},{"key":"c","text":"Reemplazar el entrenamiento"},{"key":"d","text":"Facilitar meter la mano"}],"correctOption":"a"},{"id":"hs_q12","question":"Si el guante se engancha o puede engancharse en partes móviles, se debe:","options":[{"key":"a","text":"Detenerse y aplicar el procedimiento seguro para esa tarea/equipo"},{"key":"b","text":"Acercar más la mano"},{"key":"c","text":"Continuar con más fuerza"},{"key":"d","text":"Cambiar de mano"}],"correctOption":"a"},{"id":"hs_q13","question":"Una buena práctica al cortar o usar cuchillas es:","options":[{"key":"a","text":"Cortar alejando la herramienta del cuerpo y de la otra mano"},{"key":"b","text":"Cortar hacia la palma"},{"key":"c","text":"Usar cuchillas sin mango"},{"key":"d","text":"Apoyar la mano en la línea de corte"}],"correctOption":"a"},{"id":"hs_q14","question":"¿Qué debe hacerse si cambia la tarea o aparece un nuevo riesgo para las manos?","options":[{"key":"a","text":"Detenerse, reevaluar y ajustar controles"},{"key":"b","text":"Continuar si falta poco"},{"key":"c","text":"Guardar los guantes"},{"key":"d","text":"No reportarlo"}],"correctOption":"a"},{"id":"hs_q15","question":"La conducta correcta para cuidar las manos es:","options":[{"key":"a","text":"Identificar riesgos, usar herramientas/guantes adecuados y mantener manos fuera de puntos peligrosos"},{"key":"b","text":"Confiar en la experiencia"},{"key":"c","text":"Usar cualquier guante para todo"},{"key":"d","text":"Trabajar rápido para reducir exposición"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_confined_spaces','tr_confined_spaces','{"id":"test_confined_spaces","trainingId":"tr_confined_spaces","title":"Examen Espacios Confinados","description":"Evaluación final del training Espacios Confinados, alineada con la regla IOGP Life-Saving Rules: Confined Space.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"cs_q01","question":"¿Qué debe existir antes de ingresar a un espacio confinado?","options":[{"key":"a","text":"Una autorización válida para el ingreso"},{"key":"b","text":"Solo una linterna disponible"},{"key":"c","text":"La presencia de cualquier compañero cerca"},{"key":"d","text":"La decisión individual del trabajador"}],"correctOption":"a"},{"id":"cs_q02","question":"Antes de entrar a un espacio confinado, ¿qué condición debe verificarse?","options":[{"key":"a","text":"Que el espacio esté pintado"},{"key":"b","text":"Que la atmósfera sea segura o esté controlada según el procedimiento"},{"key":"c","text":"Que la tarea sea rápida"},{"key":"d","text":"Que no haya supervisores presentes"}],"correctOption":"b"},{"id":"cs_q03","question":"¿Por qué se controla la atmósfera de un espacio confinado?","options":[{"key":"a","text":"Para evitar demoras administrativas"},{"key":"b","text":"Para confirmar que no existan gases peligrosos o falta de oxígeno"},{"key":"c","text":"Para mejorar la iluminación"},{"key":"d","text":"Para medir la temperatura exterior"}],"correctOption":"b"},{"id":"cs_q04","question":"¿Cuál es una práctica segura durante el ingreso a un espacio confinado?","options":[{"key":"a","text":"Entrar solo si se conoce el lugar"},{"key":"b","text":"Mantener comunicación y vigilancia según el plan de trabajo"},{"key":"c","text":"Cerrar el acceso para evitar interrupciones"},{"key":"d","text":"Retirar los controles para facilitar la tarea"}],"correctOption":"b"},{"id":"cs_q05","question":"Si cambian las condiciones dentro del espacio confinado, se debe:","options":[{"key":"a","text":"Continuar hasta terminar"},{"key":"b","text":"Aumentar la velocidad de trabajo"},{"key":"c","text":"Detener el trabajo, salir y reportar la situación"},{"key":"d","text":"Ignorar el cambio si no hay olor"}],"correctOption":"c"},{"id":"cs_q06","question":"Un espacio confinado puede ser peligroso porque:","options":[{"key":"a","text":"Siempre está al aire libre"},{"key":"b","text":"Puede contener atmósferas peligrosas o restricciones de ingreso/salida"},{"key":"c","text":"Siempre tiene mucho espacio para moverse"},{"key":"d","text":"No requiere controles especiales"}],"correctOption":"b"},{"id":"cs_q07","question":"¿Qué debe estar definido antes de ingresar a un espacio confinado?","options":[{"key":"a","text":"Un plan de rescate o respuesta ante emergencia"},{"key":"b","text":"La hora de almuerzo"},{"key":"c","text":"El color del casco"},{"key":"d","text":"La cantidad de fotografías a tomar"}],"correctOption":"a"},{"id":"cs_q08","question":"¿Quién debe ingresar a un espacio confinado?","options":[{"key":"a","text":"Cualquier persona disponible"},{"key":"b","text":"Solo personal autorizado y competente para la tarea"},{"key":"c","text":"El trabajador con más urgencia"},{"key":"d","text":"Quien esté más cerca del acceso"}],"correctOption":"b"},{"id":"cs_q09","question":"¿Qué debe hacerse con fuentes de energía o materiales peligrosos vinculados al espacio?","options":[{"key":"a","text":"Dejarlos activos para ahorrar tiempo"},{"key":"b","text":"Identificarlos y controlarlos antes del ingreso"},{"key":"c","text":"Controlarlos solo después de entrar"},{"key":"d","text":"Ignorarlos si no se ven"}],"correctOption":"b"},{"id":"cs_q10","question":"La autorización de ingreso sirve para:","options":[{"key":"a","text":"Confirmar que se revisaron riesgos, controles y condiciones de entrada"},{"key":"b","text":"Reemplazar la evaluación de riesgos"},{"key":"c","text":"Permitir trabajar sin comunicación"},{"key":"d","text":"Evitar el uso de equipos de protección"}],"correctOption":"a"},{"id":"cs_q11","question":"¿Qué debe hacerse si no se puede confirmar que el espacio es seguro?","options":[{"key":"a","text":"Ingresar por poco tiempo"},{"key":"b","text":"Ingresar con más cuidado"},{"key":"c","text":"No ingresar hasta que los controles estén verificados"},{"key":"d","text":"Pedir que otro trabajador ingrese primero"}],"correctOption":"c"},{"id":"cs_q12","question":"Durante el trabajo en espacio confinado, la vigilancia externa ayuda a:","options":[{"key":"a","text":"Controlar condiciones y responder ante emergencias"},{"key":"b","text":"Acelerar el llenado de formularios"},{"key":"c","text":"Reducir la necesidad de autorización"},{"key":"d","text":"Evitar que se use ventilación"}],"correctOption":"a"},{"id":"cs_q13","question":"¿Cuál de estas acciones es insegura?","options":[{"key":"a","text":"Verificar autorización antes de ingresar"},{"key":"b","text":"Entrar sin confirmar la atmósfera"},{"key":"c","text":"Mantener comunicación"},{"key":"d","text":"Respetar el plan de rescate"}],"correctOption":"b"},{"id":"cs_q14","question":"La ventilación o control de atmósfera debe usarse cuando:","options":[{"key":"a","text":"Lo requiere el análisis de riesgos o procedimiento"},{"key":"b","text":"El trabajador quiere más comodidad únicamente"},{"key":"c","text":"La tarea ya terminó"},{"key":"d","text":"No existe autorización"}],"correctOption":"a"},{"id":"cs_q15","question":"La conducta correcta ante un espacio confinado es:","options":[{"key":"a","text":"Ingresar solo con autorización, controles verificados y plan de emergencia"},{"key":"b","text":"Ingresar si el trabajo tarda poco"},{"key":"c","text":"Confiar únicamente en la experiencia"},{"key":"d","text":"Evitar reportar cambios para no detener la tarea"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_energy_isolation','tr_energy_isolation','{"id":"test_energy_isolation","trainingId":"tr_energy_isolation","title":"Examen Aislamiento de Energía","description":"Evaluación final del training Aislamiento de Energía, alineada con la regla IOGP Life-Saving Rules: Energy Isolation.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"ei_q01","question":"Antes de comenzar un trabajo con energía peligrosa, se debe:","options":[{"key":"a","text":"Verificar aislamiento y energía cero"},{"key":"b","text":"Trabajar más rápido"},{"key":"c","text":"Retirar candados existentes"},{"key":"d","text":"Confiar en que el equipo está apagado"}],"correctOption":"a"},{"id":"ei_q02","question":"¿Qué significa identificar las fuentes de energía?","options":[{"key":"a","text":"Reconocer todas las energías que pueden causar daño"},{"key":"b","text":"Elegir la fuente más cercana"},{"key":"c","text":"Revisar solo la energía eléctrica"},{"key":"d","text":"Preguntar quién encendió el equipo"}],"correctOption":"a"},{"id":"ei_q03","question":"Una fuente de energía peligrosa puede ser:","options":[{"key":"a","text":"Solo electricidad"},{"key":"b","text":"Energía eléctrica, mecánica, hidráulica, neumática, térmica o almacenada"},{"key":"c","text":"Solo combustible"},{"key":"d","text":"Solo presión atmosférica"}],"correctOption":"b"},{"id":"ei_q04","question":"Después de aislar una fuente de energía, corresponde:","options":[{"key":"a","text":"Verificar energía cero antes de intervenir"},{"key":"b","text":"Retirar etiquetas para evitar confusión"},{"key":"c","text":"Comenzar sin probar"},{"key":"d","text":"Abrir la protección de inmediato"}],"correctOption":"a"},{"id":"ei_q05","question":"El bloqueo y etiquetado ayuda a:","options":[{"key":"a","text":"Evitar la reenergización no autorizada"},{"key":"b","text":"Hacer más visible el equipo solamente"},{"key":"c","text":"Reducir la limpieza"},{"key":"d","text":"Eliminar la necesidad de permiso"}],"correctOption":"a"},{"id":"ei_q06","question":"¿Qué debe hacerse con energía residual o almacenada?","options":[{"key":"a","text":"Ignorarla si el equipo está apagado"},{"key":"b","text":"Liberarla, contenerla o controlarla según procedimiento"},{"key":"c","text":"Aumentarla para probar el equipo"},{"key":"d","text":"Dejarla para el final"}],"correctOption":"b"},{"id":"ei_q07","question":"¿Cuál es una acción insegura en aislamiento de energía?","options":[{"key":"a","text":"Colocar bloqueo autorizado"},{"key":"b","text":"Verificar energía cero"},{"key":"c","text":"Retirar un bloqueo ajeno sin autorización"},{"key":"d","text":"Identificar fuentes de energía"}],"correctOption":"c"},{"id":"ei_q08","question":"Si no se puede confirmar energía cero, se debe:","options":[{"key":"a","text":"Continuar con cuidado"},{"key":"b","text":"No comenzar hasta verificar el control de energía"},{"key":"c","text":"Pedir que otro trabajador pruebe"},{"key":"d","text":"Trabajar solo sobre una parte del equipo"}],"correctOption":"b"},{"id":"ei_q09","question":"¿Quién debe respetar los bloqueos y etiquetas?","options":[{"key":"a","text":"Solo mantenimiento"},{"key":"b","text":"Toda persona involucrada o cercana al trabajo"},{"key":"c","text":"Solo supervisores"},{"key":"d","text":"Solo operadores externos"}],"correctOption":"b"},{"id":"ei_q10","question":"El aislamiento efectivo requiere:","options":[{"key":"a","text":"Apagar desde un botón únicamente"},{"key":"b","text":"Aislar, bloquear, etiquetar y verificar"},{"key":"c","text":"Avisar verbalmente sin registrar"},{"key":"d","text":"Desconectar una parte visible solamente"}],"correctOption":"b"},{"id":"ei_q11","question":"¿Para qué se prueba la ausencia de energía?","options":[{"key":"a","text":"Para confirmar que el equipo no puede liberar energía peligrosa"},{"key":"b","text":"Para ahorrar herramientas"},{"key":"c","text":"Para evitar hacer el permiso"},{"key":"d","text":"Para registrar la temperatura"}],"correctOption":"a"},{"id":"ei_q12","question":"Una etiqueta de aislamiento indica:","options":[{"key":"a","text":"Que el equipo puede usarse libremente"},{"key":"b","text":"Que existe una condición de control que no debe alterarse sin autorización"},{"key":"c","text":"Que el trabajo terminó"},{"key":"d","text":"Que no hay riesgos"}],"correctOption":"b"},{"id":"ei_q13","question":"Antes de retirar un bloqueo, debe verificarse que:","options":[{"key":"a","text":"La tarea y las condiciones permiten retirar el control de forma segura"},{"key":"b","text":"El turno está por terminar"},{"key":"c","text":"El equipo parece limpio"},{"key":"d","text":"No haya nadie mirando"}],"correctOption":"a"},{"id":"ei_q14","question":"¿Cuál es el objetivo principal del aislamiento de energía?","options":[{"key":"a","text":"Prevenir lesiones por liberación inesperada de energía"},{"key":"b","text":"Acelerar la producción"},{"key":"c","text":"Reducir documentación"},{"key":"d","text":"Evitar capacitaciones"}],"correctOption":"a"},{"id":"ei_q15","question":"La conducta correcta antes de intervenir un equipo es:","options":[{"key":"a","text":"Identificar energías, aislar, bloquear, etiquetar y verificar energía cero"},{"key":"b","text":"Apagar y comenzar"},{"key":"c","text":"Preguntar si alguien vio riesgos"},{"key":"d","text":"Usar guantes y no aislar"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_loto_spi','tr_loto_spi','{"id":"test_loto_spi","trainingId":"tr_loto_spi","title":"Examen LOTO · Bloqueo y Etiquetado","description":"Evaluación final del training SPI LOTO, basada en HSE-INS-004 Rev.00.","passingScore":80,"questionsPerAttempt":10,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"loto_spi_q01","question":"¿Cuál es el objetivo principal de la aplicación de LOTO en SPI?","options":[{"key":"a","text":"Registrar las tareas realizadas por mantenimiento"},{"key":"b","text":"Establecer requisitos mínimos para bloquear y etiquetar fuentes de energía peligrosas"},{"key":"c","text":"Definir solamente los colores de los candados"},{"key":"d","text":"Sustituir los permisos de trabajo"}],"correctOption":"b"},{"id":"loto_spi_q02","question":"¿Dónde aplica el procedimiento LOTO de SPI?","options":[{"key":"a","text":"En todas las instalaciones y operaciones bajo el control de SPI"},{"key":"b","text":"Únicamente en talleres"},{"key":"c","text":"Solo en operaciones de terceros"},{"key":"d","text":"Exclusivamente en instalaciones eléctricas"}],"correctOption":"a"},{"id":"loto_spi_q03","question":"¿Cuál de estas combinaciones contiene fuentes de energía peligrosas contempladas en el training?","options":[{"key":"a","text":"Únicamente eléctrica y mecánica"},{"key":"b","text":"Eléctrica, mecánica, hidráulica, neumática, química y térmica"},{"key":"c","text":"Solamente hidráulica y neumática"},{"key":"d","text":"Únicamente gas y electricidad"}],"correctOption":"b"},{"id":"loto_spi_q04","question":"¿Por qué un equipo detenido puede continuar siendo peligroso?","options":[{"key":"a","text":"Porque puede tener herramientas en su interior"},{"key":"b","text":"Porque la señalización puede estar incompleta"},{"key":"c","text":"Porque puede conservar energía peligrosa o energía almacenada"},{"key":"d","text":"Porque siempre permanece conectado a una fuente eléctrica"}],"correctOption":"c"},{"id":"loto_spi_q05","question":"¿Qué significa Lockout o Bloqueo?","options":[{"key":"a","text":"Colocar únicamente una tarjeta de advertencia"},{"key":"b","text":"Aislar físicamente una fuente de energía del sistema que la utiliza"},{"key":"c","text":"Informar verbalmente que el equipo no debe utilizarse"},{"key":"d","text":"Apagar un equipo desde su control principal"}],"correctOption":"b"},{"id":"loto_spi_q06","question":"¿Qué significa Tagout o Etiquetado?","options":[{"key":"a","text":"Colocar una etiqueta o tarjeta que comunica la intervención realizada y su importancia"},{"key":"b","text":"Colocar un segundo candado"},{"key":"c","text":"Completar el permiso de trabajo"},{"key":"d","text":"Verificar el funcionamiento del equipo"}],"correctOption":"a"},{"id":"loto_spi_q07","question":"¿Qué debe asegurar el Gerente de Operaciones respecto de LOTO?","options":[{"key":"a","text":"Retirar personalmente todos los candados"},{"key":"b","text":"Los recursos necesarios para cumplir los requisitos LOTO"},{"key":"c","text":"Realizar todas las tareas de mantenimiento"},{"key":"d","text":"Auditar exclusivamente a proveedores externos"}],"correctOption":"b"},{"id":"loto_spi_q08","question":"¿Cuál es una responsabilidad del Supervisor de Operaciones?","options":[{"key":"a","text":"Autorizar trabajos sin LOTO cuando sean breves"},{"key":"b","text":"Asegurar que el personal conozca el estándar y aplicar LOTO en trabajos con energías peligrosas durante operaciones con clientes"},{"key":"c","text":"Reemplazar al responsable de mantenimiento"},{"key":"d","text":"Retirar candados colocados por terceros"}],"correctOption":"b"},{"id":"loto_spi_q09","question":"¿Cuál es una responsabilidad de QHSE?","options":[{"key":"a","text":"Operar los equipos luego de su bloqueo"},{"key":"b","text":"Proveer los diagramas del fabricante"},{"key":"c","text":"Auditar el programa y la ejecución de los procedimientos de bloqueo y etiquetado"},{"key":"d","text":"Colocar los candados de cada empleado"}],"correctOption":"c"},{"id":"loto_spi_q10","question":"¿Qué debe hacer un empleado con los dispositivos de bloqueo y etiquetado?","options":[{"key":"a","text":"Utilizarlos para cualquier necesidad operativa"},{"key":"b","text":"Compartirlos cuando otro trabajador los necesite"},{"key":"c","text":"Utilizarlos correcta y únicamente para el fin para el que fueron diseñados"},{"key":"d","text":"Retirarlos cuando considere finalizada una tarea"}],"correctOption":"c"},{"id":"loto_spi_q11","question":"¿Bajo qué condición debe realizarse toda aplicación de LOTO?","options":[{"key":"a","text":"Bajo un Permiso de Trabajo"},{"key":"b","text":"Bajo autorización verbal únicamente"},{"key":"c","text":"Sin permiso si el equipo está apagado"},{"key":"d","text":"Solo con autorización de otro trabajador"}],"correctOption":"a"},{"id":"loto_spi_q12","question":"¿Cuál es el primer paso indicado para la aislación y bloqueo de energía?","options":[{"key":"a","text":"Colocar las etiquetas"},{"key":"b","text":"Verificar el diagrama de flujo del equipo o el diagrama unifilar de la instalación"},{"key":"c","text":"Retirar los candados existentes"},{"key":"d","text":"Energizar el equipo"}],"correctOption":"b"},{"id":"loto_spi_q13","question":"Después de realizar la aislación de las energías identificadas, ¿qué debe hacerse antes de bloquear todas las fuentes?","options":[{"key":"a","text":"Poner en marcha el equipo"},{"key":"b","text":"Liberar la energía residual almacenada"},{"key":"c","text":"Retirar las protecciones"},{"key":"d","text":"Cerrar el permiso de trabajo"}],"correctOption":"b"},{"id":"loto_spi_q14","question":"¿Cuál es el orden correcto de las últimas etapas del proceso de aislamiento?","options":[{"key":"a","text":"Etiquetar → energizar → bloquear"},{"key":"b","text":"Liberar energía residual → bloquear → etiquetar → verificar ausencia de energía"},{"key":"c","text":"Verificar → retirar bloqueo → etiquetar"},{"key":"d","text":"Bloquear → comenzar la tarea → verificar"}],"correctOption":"b"},{"id":"loto_spi_q15","question":"Si se utiliza un equipo de medición para verificar ausencia de energía, ¿qué debe hacerse?","options":[{"key":"a","text":"Utilizar cualquier instrumento disponible"},{"key":"b","text":"Asegurar que esté certificado y probarlo primero en una instalación con energía"},{"key":"c","text":"Probarlo únicamente después de la intervención"},{"key":"d","text":"Utilizarlo solo si no existen diagramas"}],"correctOption":"b"},{"id":"loto_spi_q16","question":"Antes de restablecer la energía, ¿qué debe comprobarse mediante inspección visual?","options":[{"key":"a","text":"Que se retiraron las herramientas, las protecciones están instaladas y el equipo puede energizarse de forma segura"},{"key":"b","text":"Que todos los candados continúan colocados"},{"key":"c","text":"Que el permiso ya fue cerrado"},{"key":"d","text":"Que el equipo esté funcionando"}],"correctOption":"a"},{"id":"loto_spi_q17","question":"¿Cuál es el primer paso indicado para el restablecimiento de energía?","options":[{"key":"a","text":"Comunicar a todo el personal la puesta en funcionamiento del equipo o instalación"},{"key":"b","text":"Retirar inmediatamente todos los candados"},{"key":"c","text":"Energizar el equipo"},{"key":"d","text":"Cerrar el permiso"}],"correctOption":"a"},{"id":"loto_spi_q18","question":"Si la persona responsable de un candado no está presente, ¿qué debe hacerse inicialmente?","options":[{"key":"a","text":"Cortar el candado"},{"key":"b","text":"Pedir a otro trabajador que lo retire"},{"key":"c","text":"Comunicar inmediatamente al Gerente del sector y a QHSE para intentar contactar al responsable"},{"key":"d","text":"Energizar el equipo para verificar si funciona"}],"correctOption":"c"},{"id":"loto_spi_q19","question":"Si no es posible localizar al responsable del candado, ¿qué debe realizarse antes de retirarlo?","options":[{"key":"a","text":"Una inspección visual únicamente"},{"key":"b","text":"Una autorización verbal"},{"key":"c","text":"Una evaluación de riesgos previa a la remoción"},{"key":"d","text":"Una nueva capacitación"}],"correctOption":"c"},{"id":"loto_spi_q20","question":"¿Cuál es la combinación correcta de colores de candados utilizada por SPI?","options":[{"key":"a","text":"Operaciones rojo, Mantenimiento azul, Proveedores Externos amarillo"},{"key":"b","text":"Operaciones amarillo, Mantenimiento rojo, Proveedores Externos azul"},{"key":"c","text":"Operaciones azul, Mantenimiento amarillo, Proveedores Externos rojo"},{"key":"d","text":"Todos utilizan el mismo color"}],"correctOption":"a"},{"id":"loto_spi_q21","question":"¿Qué palabras debe mostrar claramente una etiqueta LOTO?","options":[{"key":"a","text":"PRECAUCIÓN y EQUIPO APAGADO"},{"key":"b","text":"PELIGRO y NO OPERAR"},{"key":"c","text":"MANTENIMIENTO y ESPERAR"},{"key":"d","text":"DETENIDO y REVISAR"}],"correctOption":"b"},{"id":"loto_spi_q22","question":"¿Qué información debe incluir la etiqueta de bloqueo?","options":[{"key":"a","text":"Solamente el número del equipo"},{"key":"b","text":"La fecha del bloqueo y el nombre de la persona que aplica el bloqueo"},{"key":"c","text":"Únicamente la hora de inicio"},{"key":"d","text":"El nombre del fabricante"}],"correctOption":"b"},{"id":"loto_spi_q23","question":"¿Qué colores debe utilizar la etiqueta LOTO indicada en el training?","options":[{"key":"a","text":"Azul, blanco y amarillo"},{"key":"b","text":"Amarillo y negro"},{"key":"c","text":"Rojo, negro y blanco"},{"key":"d","text":"Rojo y azul"}],"correctOption":"c"},{"id":"loto_spi_q24","question":"Según el formato de tarjeta presentado, ¿quién puede quitarla una vez finalizados los trabajos?","options":[{"key":"a","text":"Cualquier supervisor"},{"key":"b","text":"Cualquier trabajador autorizado"},{"key":"c","text":"La persona autorizada indicada en la tarjeta"},{"key":"d","text":"El último trabajador que abandone el área"}],"correctOption":"c"},{"id":"loto_spi_q25","question":"¿Cuáles son las dimensiones indicadas para la tarjeta presentada en el training?","options":[{"key":"a","text":"100 mm × 50 mm"},{"key":"b","text":"145 mm × 75 mm"},{"key":"c","text":"200 mm × 100 mm"},{"key":"d","text":"75 mm × 40 mm"}],"correctOption":"b"},{"id":"loto_spi_q26","question":"¿Cuál de los siguientes puede utilizarse como elemento de aislamiento físico?","options":[{"key":"a","text":"Únicamente una etiqueta"},{"key":"b","text":"Candados, bridas ciegas u otros dispositivos adecuados a la aplicación"},{"key":"c","text":"Solo una señal verbal"},{"key":"d","text":"Únicamente interruptores eléctricos"}],"correctOption":"b"},{"id":"loto_spi_q27","question":"¿Qué debe hacerse con un dispositivo de aislamiento que tiene una etiqueta de PELIGRO adherida?","options":[{"key":"a","text":"Operarlo si la tarea ya terminó"},{"key":"b","text":"Operarlo únicamente con autorización verbal"},{"key":"c","text":"No operarlo bajo ninguna circunstancia mientras la etiqueta esté adherida"},{"key":"d","text":"Probarlo antes de retirar la etiqueta"}],"correctOption":"c"},{"id":"loto_spi_q28","question":"¿Para qué pueden utilizarse los candados LOTO?","options":[{"key":"a","text":"Para cerrar herramientas y depósitos"},{"key":"b","text":"Exclusivamente para tareas de bloqueo de equipos"},{"key":"c","text":"Para cualquier uso de seguridad"},{"key":"d","text":"Para identificar pertenencias personales"}],"correctOption":"b"},{"id":"loto_spi_q29","question":"Durante la desenergización, ¿qué debe hacerse si al verificar el sistema NO se alcanza condición de “energía cero”?","options":[{"key":"a","text":"Continuar con la tarea con mayor precaución"},{"key":"b","text":"Retirar los bloqueos"},{"key":"c","text":"Detener la tarea y volver a revisar la información y las fuentes de energía"},{"key":"d","text":"Reenergizar y comenzar la tarea igualmente"}],"correctOption":"c"},{"id":"loto_spi_q30","question":"En el flujo de reenergización, ¿qué ocurre después de reenergizar el equipo?","options":[{"key":"a","text":"Se coloca nuevamente el bloqueo"},{"key":"b","text":"Se inicia una nueva intervención"},{"key":"c","text":"Se verifica el funcionamiento del equipo o instalación y luego se cierra el permiso"},{"key":"d","text":"Se retiran los diagramas del equipo"}],"correctOption":"c"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_spi_pman_m01','tr_spi_pman_m01','{"id":"test_spi_pman_m01","trainingId":"tr_spi_pman_m01","title":"Examen · Protección de Manos · Módulo 1 · Riesgos y Prevención","description":"Evaluación de Protección de Manos SPI. Banco de 30 preguntas en 3 baterías consecutivas de 10.","passingScore":80,"questionsPerAttempt":10,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"SPI-PMAN-M01-B1-P01","question":"¿Cuál de estas lesiones de manos suele aparecer con el tiempo y no por un único evento?","options":[{"key":"a","text":"Las fracturas por un golpe con maza o martillo."},{"key":"b","text":"Las lesiones por esfuerzo repetitivo o vibración."},{"key":"c","text":"Las laceraciones por bordes filosos o rebabas."},{"key":"d","text":"Los aplastamientos entre dos piezas que se mueven al mismo tiempo."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B1-P02","question":"¿Qué es el efecto látigo?","options":[{"key":"a","text":"El rebote de la maza hacia la mano cuando golpea una superficie dura o metálica."},{"key":"b","text":"La vibración que transmite una herramienta eléctrica a la mano durante un uso prolongado."},{"key":"c","text":"Transmisión de energía por golpe indirecto."},{"key":"d","text":"El tirón brusco que se siente en la muñeca al levantar una carga manual pesada."}],"correctOption":"c"},{"id":"SPI-PMAN-M01-B1-P03","question":"Una herramienta debe sostenerse mientras recibe golpes de maza. ¿Qué medida corresponde priorizar?","options":[{"key":"a","text":"Utilizar un dispositivo manos libres para sostenerla."},{"key":"b","text":"Usar guantes de impacto y sujetarla con firmeza con la mano."},{"key":"c","text":"Sujetarla con ambas manos para que no se mueva."},{"key":"d","text":"Golpear con menos fuerza para reducir el impacto."}],"correctOption":"a"},{"id":"SPI-PMAN-M01-B1-P04","question":"¿Qué define a un punto de pellizco?","options":[{"key":"a","text":"Que un objeto se mueva con fuerza propia y pueda impactar directamente la mano."},{"key":"b","text":"Que haya bordes filosos o rebabas expuestas en la pieza o la herramienta."},{"key":"c","text":"Que exista una superficie caliente que pueda provocar quemaduras al tocarla."},{"key":"d","text":"Que la mano pueda quedar atrapada entre un objeto móvil y otro fijo o móvil."}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B1-P05","question":"Un operador ajusta una conexión, la llave se resbala y su mano impacta contra la estructura del equipo. ¿Qué tipo de golpe es?","options":[{"key":"a","text":"Golpe por."},{"key":"b","text":"Atrapamiento."},{"key":"c","text":"Efecto látigo."},{"key":"d","text":"Golpe contra."}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B1-P06","question":"¿Qué tienen en común la maquinaria, los martillos, las herramientas de perforación, las cargas manuales y la manipulación de tuberías?","options":[{"key":"a","text":"Todos requieren un permiso de trabajo en caliente antes de empezar."},{"key":"b","text":"Todos se controlan solamente con el uso de guantes de alto impacto adecuados."},{"key":"c","text":"Todos pueden generar puntos de atrapamiento o de golpe para las manos."},{"key":"d","text":"Todos generan principalmente riesgo eléctrico para quien los opera."}],"correctOption":"c"},{"id":"SPI-PMAN-M01-B1-P07","question":"Antes de hacer fuerza sobre una llave, ¿qué pregunta clave hay que hacerse?","options":[{"key":"a","text":"¿Qué pasa con mis manos si la herramienta se suelta?"},{"key":"b","text":"¿La llave es del tamaño justo para no dañar la tuerca?"},{"key":"c","text":"¿Cuánto tiempo me queda para terminar la tarea?"},{"key":"d","text":"¿Mis guantes son los más resistentes disponibles?"}],"correctOption":"a"},{"id":"SPI-PMAN-M01-B1-P08","question":"Al analizar incidentes con lesiones en manos, ¿cuál de estos factores se encontró?","options":[{"key":"a","text":"Las herramientas eran nuevas y todavía no estaban probadas en campo."},{"key":"b","text":"Las personas no identificaron los peligros antes de empezar."},{"key":"c","text":"Los equipos tenían demasiadas protecciones."},{"key":"d","text":"Las tareas se planificaban con demasiada anticipación."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B1-P09","question":"¿Cuál de estas situaciones es un factor humano que aumenta la posibilidad de un incidente?","options":[{"key":"a","text":"Usar una llave de torque hidráulica para el ajuste."},{"key":"b","text":"Reportar un peligro antes de empezar la tarea."},{"key":"c","text":"Tomar atajos y sentir presión por terminar rápido."},{"key":"d","text":"Detenerse a mirar el lugar antes de comenzar."}],"correctOption":"c"},{"id":"SPI-PMAN-M01-B1-P10","question":"¿Cuál es el paso más importante antes de comenzar una tarea?","options":[{"key":"a","text":"Ponerse los guantes y comenzar la tarea cuanto antes."},{"key":"b","text":"Preguntar cuánto tiempo hay disponible para terminar el trabajo."},{"key":"c","text":"Elegir la herramienta más grande y resistente que haya disponible."},{"key":"d","text":"Identificar los peligros del lugar, el equipo y las herramientas."}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B2-P01","question":"¿Por qué una lesión en una mano no afecta solo al trabajo?","options":[{"key":"a","text":"Porque las lesiones de manos siempre requieren cirugía y largos meses de recuperación."},{"key":"b","text":"Porque puede afectar la vida diaria, la familia y la capacidad de trabajar."},{"key":"c","text":"Porque las manos se lesionan con más frecuencia en casa que en el lugar de trabajo."},{"key":"d","text":"Porque toda lesión de manos deja una secuela permanente, aunque sea leve."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B2-P02","question":"¿Qué significa estar en la línea de fuego?","options":[{"key":"a","text":"Trabajar cerca de equipos que tienen riesgo de incendio o fuentes de calor sin ninguna protección."},{"key":"b","text":"Ocupar el puesto de mayor responsabilidad y exposición dentro del equipo de trabajo."},{"key":"c","text":"Estar en la trayectoria de la energía de un golpe, una pieza o un elemento con tensión."},{"key":"d","text":"Estar expuesto al calor que despide un equipo en funcionamiento durante la tarea."}],"correctOption":"c"},{"id":"SPI-PMAN-M01-B2-P03","question":"¿Por qué no se debe golpear una herramienta manual que no está diseñada para eso?","options":[{"key":"a","text":"Porque puede romperse, desprender fragmentos o transmitir energía a las manos."},{"key":"b","text":"Porque pierde la garantía del fabricante y después no se puede reclamar."},{"key":"c","text":"Porque se desgasta más rápido y hay que reemplazarla antes de lo previsto."},{"key":"d","text":"Porque pierde precisión y afecta la calidad de los próximos ajustes que se hagan."}],"correctOption":"a"},{"id":"SPI-PMAN-M01-B2-P04","question":"Estás ajustando una conexión y tus dedos quedan entre la boca de la llave y la conexión. ¿Qué riesgo hay si la llave gira o se suelta?","options":[{"key":"a","text":"Que la mano sufra una quemadura por la fricción con la llave."},{"key":"b","text":"Que se produzca un corte por una rebaba de la conexión."},{"key":"c","text":"Que la llave se dañe y haya que reemplazarla."},{"key":"d","text":"Que los dedos queden atrapados en un punto de pellizco."}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B2-P05","question":"Una herramienta cae desde una plataforma y golpea la mano de un trabajador. ¿Qué tipo de golpe es?","options":[{"key":"a","text":"Golpe contra."},{"key":"b","text":"Punto de pellizco."},{"key":"c","text":"Atrapamiento entre dos objetos móviles."},{"key":"d","text":"Golpe por."}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B2-P06","question":"Al usar un martillo sobre una pieza, ¿qué mano suele quedar más expuesta?","options":[{"key":"a","text":"La que sostiene o apoya la pieza, porque puede quedar en la trayectoria del golpe."},{"key":"b","text":"La que sostiene el martillo, por la vibración que transmite el mango en cada golpe."},{"key":"c","text":"Ninguna de las dos, siempre que se usen guantes de impacto adecuados."},{"key":"d","text":"Las dos por igual, sin importar dónde estén ubicadas durante la tarea."}],"correctOption":"a"},{"id":"SPI-PMAN-M01-B2-P07","question":"¿Cuál es la medida de protección más directa para evitar lesiones en las manos?","options":[{"key":"a","text":"El uso de guantes de alto impacto adecuados para cada tarea."},{"key":"b","text":"La posición de las manos: no ponerlas donde puedan estar en riesgo."},{"key":"c","text":"La firma del permiso de trabajo antes de comenzar cualquier tarea."},{"key":"d","text":"La experiencia y la habilidad del operador para realizar la tarea."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B2-P08","question":"Un trabajador usa una llave como palanca porque no tiene a mano la herramienta correcta. ¿Qué factor contribuyente representa?","options":[{"key":"a","text":"Falta de equipos de protección personal adecuados."},{"key":"b","text":"Uso incorrecto de las herramientas provistas."},{"key":"c","text":"Falta de señalización en el equipo."},{"key":"d","text":"Golpe contra objeto."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B2-P09","question":"Al hablar de factores humanos como las distracciones o los apuros, ¿cuál es el enfoque correcto?","options":[{"key":"a","text":"Identificar al responsable de cada error para poder sancionarlo a tiempo."},{"key":"b","text":"Asumir que estas situaciones solo les pasan a las personas con poca experiencia."},{"key":"c","text":"No buscar culpables: la planificación, los tiempos y el entorno también influyen."},{"key":"d","text":"Resolverlo exclusivamente sumando más supervisión en cada una de las tareas."}],"correctOption":"c"},{"id":"SPI-PMAN-M01-B2-P10","question":"¿Cuál de estas es una de las tres preguntas para identificar peligros antes de actuar?","options":[{"key":"a","text":"¿Quién es el responsable si algo sale mal?"},{"key":"b","text":"¿Cuánto tiempo lleva normalmente esta tarea?"},{"key":"c","text":"¿Hay algún compañero disponible para ayudarme?"},{"key":"d","text":"¿Dónde puede quedar atrapada mi mano?"}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B3-P01","question":"Además de cortes, aplastamientos y fracturas, ¿qué otras lesiones de manos se mencionan en la capacitación?","options":[{"key":"a","text":"Esguinces de muñeca, tendinitis de codo y contracturas."},{"key":"b","text":"Congelamiento, ampollas por fricción y calambres."},{"key":"c","text":"Dermatitis, alergias al látex y uñas encarnadas."},{"key":"d","text":"Quemaduras, electrocución e infecciones."}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B3-P02","question":"Antes de intervenir un equipo donde puede haber energía acumulada, ¿qué es lo correcto?","options":[{"key":"a","text":"Identificar la línea de fuego y controlar la energía antes de intervenir."},{"key":"b","text":"Ponerse guantes de alto impacto y comenzar la tarea con precaución."},{"key":"c","text":"Pedirle a un compañero que sostenga el elemento mientras se trabaja."},{"key":"d","text":"Golpear suavemente el equipo para comprobar si todavía queda tensión acumulada."}],"correctOption":"a"},{"id":"SPI-PMAN-M01-B3-P03","question":"¿Para qué sirven las herramientas manos libres?","options":[{"key":"a","text":"Para poder trabajar sin necesidad de usar guantes ni otro EPP."},{"key":"b","text":"Para terminar la tarea en menos tiempo."},{"key":"c","text":"Para mantener las manos alejadas de la zona de peligro."},{"key":"d","text":"Para que una sola persona pueda hacer el trabajo de dos."}],"correctOption":"c"},{"id":"SPI-PMAN-M01-B3-P04","question":"¿En qué dos situaciones la mano puede quedar pellizcada o atrapada?","options":[{"key":"a","text":"Entre dos objetos fijos, o entre un objeto fijo y el piso."},{"key":"b","text":"Entre un objeto móvil y uno fijo, o entre dos objetos móviles."},{"key":"c","text":"Solo cuando la máquina está encendida y le faltan las protecciones."},{"key":"d","text":"Solo cuando se trabaja sin guantes o con guantes dañados."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B3-P05","question":"¿Qué diferencia un golpe por de un golpe contra?","options":[{"key":"a","text":"La gravedad de la lesión: el golpe por es leve y el golpe contra es grave."},{"key":"b","text":"La herramienta usada: el golpe por es con martillo y el golpe contra es con llave."},{"key":"c","text":"De dónde viene la fuerza: del objeto (golpe por) o de la persona (golpe contra)."},{"key":"d","text":"El lugar donde ocurre: el golpe por en el taller y el golpe contra en campo."}],"correctOption":"c"},{"id":"SPI-PMAN-M01-B3-P06","question":"Las rebabas y los bordes filosos de piezas y herramientas pueden provocar principalmente:","options":[{"key":"a","text":"Quemaduras."},{"key":"b","text":"Cortes y laceraciones."},{"key":"c","text":"Lesiones por vibración."},{"key":"d","text":"Electrocución."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B3-P07","question":"Mientras una mano sostiene la maza, ¿qué hay que verificar sobre la otra mano?","options":[{"key":"a","text":"Que quede fuera del alcance y de la trayectoria del golpe."},{"key":"b","text":"Que sostenga la pieza lo más cerca posible del punto de impacto."},{"key":"c","text":"Que tenga un guante más grueso que la mano que golpea."},{"key":"d","text":"Que quede apoyada sobre la pieza para darle estabilidad."}],"correctOption":"a"},{"id":"SPI-PMAN-M01-B3-P08","question":"¿Qué tienen en común no identificar peligros, no planificar, no seguir procedimientos y usar mal las herramientas?","options":[{"key":"a","text":"Todos dependen solamente de la supervisión que haya en el lugar."},{"key":"b","text":"Todos aparecen de forma imprevista y no hay manera de anticiparlos a tiempo."},{"key":"c","text":"Todos se resuelven entregando guantes más resistentes al personal."},{"key":"d","text":"Todos se pueden detectar y corregir antes de que alguien se lastime."}],"correctOption":"d"},{"id":"SPI-PMAN-M01-B3-P09","question":"Mientras ajustás una conexión, un compañero te habla y te das vuelta para responder. ¿Qué factor humano aparece?","options":[{"key":"a","text":"Usar una herramienta inadecuada para la tarea."},{"key":"b","text":"Conversar o ser interrumpido durante la tarea."},{"key":"c","text":"No seguir el procedimiento escrito de la tarea."},{"key":"d","text":"Falta de planificación del trabajo."}],"correctOption":"b"},{"id":"SPI-PMAN-M01-B3-P10","question":"La pregunta «¿Tengo la herramienta adecuada y la uso bien?» apunta a prevenir:","options":[{"key":"a","text":"Demoras en la entrega del trabajo por tener que repetir la tarea."},{"key":"b","text":"Daños en el equipo por falta de mantenimiento."},{"key":"c","text":"Lesiones por usar herramientas no aptas o de forma incorrecta."},{"key":"d","text":"Errores al completar la documentación y los permisos de la tarea."}],"correctOption":"c"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_spi_pman_m02','tr_spi_pman_m02','{"id":"test_spi_pman_m02","trainingId":"tr_spi_pman_m02","title":"Examen · Protección de Manos · Módulo 2 · Control y Reducción de Riesgos","description":"Evaluación de Protección de Manos SPI. Banco de 30 preguntas en 3 baterías consecutivas de 10.","passingScore":80,"questionsPerAttempt":10,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"SPI-PMAN-M02-B1-P01","question":"¿Cuál es el orden correcto de la jerarquía de controles, de mayor a menor eficacia?","options":[{"key":"a","text":"EPP, administrativos, ingeniería, sustitución y eliminación."},{"key":"b","text":"Eliminación, sustitución, ingeniería, administrativos y EPP."},{"key":"c","text":"Sustitución, eliminación, ingeniería, EPP y administrativos."},{"key":"d","text":"Ingeniería, eliminación, administrativos, sustitución y EPP."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B1-P02","question":"Para evitar que un incidente se repita, ¿qué nivel de la jerarquía de controles es el más eficaz?","options":[{"key":"a","text":"Eliminación."},{"key":"b","text":"Sustitución."},{"key":"c","text":"Controles administrativos."},{"key":"d","text":"Equipos de protección personal."}],"correctOption":"a"},{"id":"SPI-PMAN-M02-B1-P03","question":"¿En qué consiste la eliminación?","options":[{"key":"a","text":"En reemplazar la herramienta por otra más segura."},{"key":"b","text":"En quitar el peligro del proceso."},{"key":"c","text":"En señalizar el peligro para que todos lo conozcan."},{"key":"d","text":"En reducir el tiempo de exposición al peligro."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B1-P04","question":"Un equipo deja de golpear una llave con martillo y adopta una llave de torque hidráulica para no exponer las manos al impacto. ¿Qué nivel de control aplicó?","options":[{"key":"a","text":"Eliminación."},{"key":"b","text":"Controles de ingeniería."},{"key":"c","text":"Sustitución."},{"key":"d","text":"Controles administrativos."}],"correctOption":"c"},{"id":"SPI-PMAN-M02-B1-P05","question":"Se rediseña una herramienta de ensamblaje y se le instalan manijas para que los dedos queden fuera de la zona de atrapamiento. ¿Qué tipo de control es?","options":[{"key":"a","text":"Eliminación."},{"key":"b","text":"Control de ingeniería."},{"key":"c","text":"Control administrativo."},{"key":"d","text":"Sustitución."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B1-P06","question":"Tras incidentes por pellizcos al colocar una protección, se identifican los puntos de pellizco con calcomanías. ¿A qué nivel de la jerarquía corresponde?","options":[{"key":"a","text":"Controles administrativos."},{"key":"b","text":"Eliminación."},{"key":"c","text":"Controles de ingeniería."},{"key":"d","text":"Equipos de protección personal."}],"correctOption":"a"},{"id":"SPI-PMAN-M02-B1-P07","question":"¿Cuáles son las dos acciones clave de la evaluación previa del trabajo?","options":[{"key":"a","text":"Firmar el permiso de trabajo y comenzar la tarea enseguida."},{"key":"b","text":"Revisar el EPP y avisar al supervisor al terminar."},{"key":"c","text":"Calcular el tiempo de la tarea y asignar responsables."},{"key":"d","text":"Identificar los peligros de cada tarea e informarlos."}],"correctOption":"d"},{"id":"SPI-PMAN-M02-B1-P08","question":"¿Cuál es la característica fundamental del EPP, como los guantes de impacto?","options":[{"key":"a","text":"Elimina el riesgo de raíz si se usa correctamente."},{"key":"b","text":"Es el control más eficaz de la jerarquía."},{"key":"c","text":"Reemplaza a los controles de ingeniería."},{"key":"d","text":"Es la última línea de defensa."}],"correctOption":"d"},{"id":"SPI-PMAN-M02-B1-P09","question":"Observás a un compañero que golpea con un martillo una pieza que sostiene con la otra mano. ¿Qué pregunta te ayuda a detectar el peligro?","options":[{"key":"a","text":"¿El martillo es de la marca y el peso recomendados?"},{"key":"b","text":"¿Cuánto tiempo le falta para terminar la tarea que está haciendo?"},{"key":"c","text":"¿Dónde está la otra mano y qué pasa si el golpe se desvía?"},{"key":"d","text":"¿El martillo es nuevo o ya fue usado en otras tareas?"}],"correctOption":"c"},{"id":"SPI-PMAN-M02-B1-P10","question":"Tenés que ajustar una conexión con una llave grande. Según la jerarquía, ¿cuál es la primera pregunta que te tenés que hacer?","options":[{"key":"a","text":"¿Qué EPP necesito para hacer esta tarea?"},{"key":"b","text":"¿Hay un procedimiento para esta tarea?"},{"key":"c","text":"¿Se puede rediseñar la herramienta que uso?"},{"key":"d","text":"¿Se puede eliminar el peligro o la tarea?"}],"correctOption":"d"},{"id":"SPI-PMAN-M02-B2-P01","question":"¿Cómo se aplica la jerarquía de controles?","options":[{"key":"a","text":"De abajo hacia arriba: primero el EPP y después los demás controles."},{"key":"b","text":"Se elige un solo nivel, según el presupuesto disponible."},{"key":"c","text":"De arriba hacia abajo: primero eliminar y el EPP al final."},{"key":"d","text":"En cualquier orden, porque todos los niveles son igual de eficaces."}],"correctOption":"c"},{"id":"SPI-PMAN-M02-B2-P02","question":"Cuanto más alto está un control en la jerarquía…","options":[{"key":"a","text":"…mayor es su eficacia y menos depende de las personas."},{"key":"b","text":"…más depende de que cada persona lo cumpla correctamente."},{"key":"c","text":"…más barato y rápido resulta implementarlo."},{"key":"d","text":"…más supervisión necesita para funcionar bien."}],"correctOption":"a"},{"id":"SPI-PMAN-M02-B2-P03","question":"Un trabajador se cortó el pulgar al abrir la parte inferior de un bolsón con un cuchillo, y se eliminó la carga de producto por caída del contenido. ¿Por qué es la mejor opción?","options":[{"key":"a","text":"Porque se entregó un cuchillo de mejor calidad."},{"key":"b","text":"Porque al eliminar la tarea, desaparece el riesgo de corte."},{"key":"c","text":"Porque el trabajador ahora usa guantes anticorte durante la tarea."},{"key":"d","text":"Porque se colocó un cartel de advertencia en los bolsones."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B2-P04","question":"¿En qué consiste la sustitución?","options":[{"key":"a","text":"En quitar por completo la tarea peligrosa del proceso de trabajo."},{"key":"b","text":"En rediseñar el equipo o la herramienta para que las manos queden alejadas."},{"key":"c","text":"En reforzar los procedimientos de trabajo y la supervisión."},{"key":"d","text":"En reemplazar la tarea, herramienta o método por algo más seguro."}],"correctOption":"d"},{"id":"SPI-PMAN-M02-B2-P05","question":"¿Qué ventaja tiene un control de ingeniería frente a uno administrativo?","options":[{"key":"a","text":"Es más rápido y económico de implementar que un procedimiento."},{"key":"b","text":"La protección queda en el equipo y depende menos de la persona."},{"key":"c","text":"No requiere ningún tipo de mantenimiento ni de revisión."},{"key":"d","text":"Reemplaza la necesidad de evaluar la tarea antes de empezar."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B2-P06","question":"¿Cuál es la principal limitación de los controles administrativos?","options":[{"key":"a","text":"Dependen de que todas las personas los conozcan y los cumplan."},{"key":"b","text":"Son los controles más caros de toda la jerarquía de controles."},{"key":"c","text":"Solo se pueden aplicar en equipos nuevos o recién instalados."},{"key":"d","text":"Eliminan el peligro, pero frenan la producción de la operación."}],"correctOption":"a"},{"id":"SPI-PMAN-M02-B2-P07","question":"¿En qué nivel de la jerarquía se ubica la evaluación previa del trabajo?","options":[{"key":"a","text":"Eliminación."},{"key":"b","text":"Controles de ingeniería."},{"key":"c","text":"Controles administrativos."},{"key":"d","text":"Equipos de protección personal."}],"correctOption":"c"},{"id":"SPI-PMAN-M02-B2-P08","question":"Un trabajador se golpeó el pulgar usando una maza sobre un fluid end, y se le entregaron guantes de alto impacto. ¿Qué logra esa medida?","options":[{"key":"a","text":"Elimina por completo el riesgo de golpe en esa tarea."},{"key":"b","text":"Reduce las consecuencias del golpe, pero no evita que ocurra."},{"key":"c","text":"Evita que la mano quede en la trayectoria de la maza al golpear."},{"key":"d","text":"Reemplaza la necesidad de evaluar la tarea."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B2-P09","question":"Al observar una tarea para buscar peligros para las manos, ¿qué conviene revisar?","options":[{"key":"a","text":"Solamente que la persona tenga los guantes puestos y que estén en buen estado."},{"key":"b","text":"El orden, la limpieza y el estado del vestuario de la persona."},{"key":"c","text":"Que la tarea se termine dentro del tiempo previsto por el supervisor."},{"key":"d","text":"La otra mano, los bordes que puedan atrapar y el estado de la herramienta."}],"correctOption":"d"},{"id":"SPI-PMAN-M02-B2-P10","question":"Al elegir cómo controlar un peligro, ¿cuándo se define el EPP necesario?","options":[{"key":"a","text":"Al final, después de evaluar los otros cuatro niveles."},{"key":"b","text":"Al principio, antes de analizar cualquier otro control."},{"key":"c","text":"Solo si no existe un procedimiento escrito para la tarea."},{"key":"d","text":"Nunca: si hay otros controles, el EPP ya no hace falta."}],"correctOption":"a"},{"id":"SPI-PMAN-M02-B3-P01","question":"¿Para qué sirve la jerarquía de controles?","options":[{"key":"a","text":"Para definir quién es el responsable de cada tarea en la operación."},{"key":"b","text":"Para clasificar las lesiones según su gravedad."},{"key":"c","text":"Para decidir qué EPP comprar para cada puesto."},{"key":"d","text":"Para ordenar las medidas de prevención según su eficacia."}],"correctOption":"d"},{"id":"SPI-PMAN-M02-B3-P02","question":"¿Por qué los controles administrativos y el EPP están en los niveles más bajos de la jerarquía?","options":[{"key":"a","text":"Porque dependen más de las personas y de la supervisión."},{"key":"b","text":"Porque son los controles más caros de implementar en la operación."},{"key":"c","text":"Porque no tienen ninguna utilidad real en la prevención."},{"key":"d","text":"Porque solo se aplican después de un incidente."}],"correctOption":"a"},{"id":"SPI-PMAN-M02-B3-P03","question":"Si un peligro se puede eliminar, ¿qué conviene hacer?","options":[{"key":"a","text":"Priorizar el EPP, porque protege directamente a la persona."},{"key":"b","text":"Señalizarlo, porque es más rápido de implementar."},{"key":"c","text":"Eliminarlo, porque es la opción más eficaz de la jerarquía."},{"key":"d","text":"Mantenerlo y capacitar al personal para que lo evite."}],"correctOption":"c"},{"id":"SPI-PMAN-M02-B3-P04","question":"En el caso de la llave de torque hidráulica, ¿qué se logró con la sustitución?","options":[{"key":"a","text":"Que nadie tenga que sostener la llave mientras se golpea."},{"key":"b","text":"Que la llave sea más liviana y fácil de transportar en campo."},{"key":"c","text":"Que el golpe con martillo sea más preciso."},{"key":"d","text":"Que el trabajador pueda usar guantes de mayor resistencia."}],"correctOption":"a"},{"id":"SPI-PMAN-M02-B3-P05","question":"¿Qué hacen los controles de ingeniería?","options":[{"key":"a","text":"Quitan por completo la tarea peligrosa del proceso de trabajo."},{"key":"b","text":"Modifican o rediseñan el equipo, la herramienta o el proceso."},{"key":"c","text":"Definen procedimientos, señalización y prácticas de trabajo seguro."},{"key":"d","text":"Protegen el cuerpo del trabajador con equipos personales."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B3-P06","question":"¿Cuál de estas medidas es un control administrativo?","options":[{"key":"a","text":"Instalar manijas rediseñadas en la herramienta de ensamblaje."},{"key":"b","text":"Reemplazar el martillo y la llave por una llave de torque hidráulica."},{"key":"c","text":"Un procedimiento que indica cómo tomar la pieza durante la tarea."},{"key":"d","text":"Entregar guantes de alto impacto a quienes realizan la tarea."}],"correctOption":"c"},{"id":"SPI-PMAN-M02-B3-P07","question":"Durante la evaluación previa detectás un peligro para las manos. ¿Qué tenés que hacer?","options":[{"key":"a","text":"Seguir con la tarea y comentarlo al terminar la jornada."},{"key":"b","text":"Reportarlo para que se corrija o elimine."},{"key":"c","text":"Usar guantes más resistentes y continuar."},{"key":"d","text":"Resolverlo por tu cuenta sin avisarle a nadie."}],"correctOption":"b"},{"id":"SPI-PMAN-M02-B3-P08","question":"¿Por qué el EPP no reemplaza a los demás controles?","options":[{"key":"a","text":"Porque es demasiado caro como para usarlo en todas las tareas de la operación."},{"key":"b","text":"Porque solo es obligatorio en algunas operaciones y no en todas."},{"key":"c","text":"Porque se desgasta con el uso y hay que cambiarlo muy seguido."},{"key":"d","text":"Porque no evita el golpe ni el atrapamiento: solo reduce las consecuencias."}],"correctOption":"d"},{"id":"SPI-PMAN-M02-B3-P09","question":"¿Cuándo conviene hacer el ejercicio de búsqueda de peligros en tu lugar de trabajo?","options":[{"key":"a","text":"Solo después de que ocurre un incidente, para investigar sus causas."},{"key":"b","text":"Una vez al año, durante la auditoría de seguridad."},{"key":"c","text":"Antes de cada tarea, para detectar los peligros a tiempo."},{"key":"d","text":"Solo cuando la tarea es nueva para el equipo de trabajo."}],"correctOption":"c"},{"id":"SPI-PMAN-M02-B3-P10","question":"¿Cuál es el objetivo de recorrer la jerarquía en orden al elegir un control?","options":[{"key":"a","text":"Priorizar los controles más eficaces y no depender solo del EPP."},{"key":"b","text":"Cumplir con un trámite obligatorio antes de empezar la tarea."},{"key":"c","text":"Elegir siempre el control más económico y más rápido de aplicar en campo."},{"key":"d","text":"Asegurar que todos usen el mismo tipo de guante en la tarea."}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_line_of_fire','tr_line_of_fire','{"id":"test_line_of_fire","trainingId":"tr_line_of_fire","title":"Examen Línea de Fuego","description":"Evaluación final del training Línea de Fuego, alineada con la regla IOGP Life-Saving Rules: Line of Fire.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"lof_q01","question":"La regla Línea de Fuego busca que las personas:","options":[{"key":"a","text":"Se mantengan fuera de zonas donde puedan ser golpeadas, atrapadas o alcanzadas"},{"key":"b","text":"Trabajen más cerca de equipos móviles"},{"key":"c","text":"Eviten reportar objetos sueltos"},{"key":"d","text":"Permanezcan debajo de cargas"}],"correctOption":"a"},{"id":"lof_q02","question":"¿Cuál de estos ejemplos representa una línea de fuego?","options":[{"key":"a","text":"Una zona con objetos en movimiento"},{"key":"b","text":"Una oficina cerrada"},{"key":"c","text":"Un comedor"},{"key":"d","text":"Un plano impreso"}],"correctOption":"a"},{"id":"lof_q03","question":"Para evitar la línea de fuego, debo posicionarme lejos de:","options":[{"key":"a","text":"Objetos en movimiento, vehículos, liberaciones de presión y objetos que puedan caer"},{"key":"b","text":"Carteles de seguridad"},{"key":"c","text":"Zonas iluminadas"},{"key":"d","text":"Salidas de emergencia"}],"correctOption":"a"},{"id":"lof_q04","question":"Las barreras y zonas de exclusión sirven para:","options":[{"key":"a","text":"Mantener a las personas fuera del área de peligro"},{"key":"b","text":"Decorar el área"},{"key":"c","text":"Aumentar la circulación"},{"key":"d","text":"Evitar que se informe el riesgo"}],"correctOption":"a"},{"id":"lof_q05","question":"¿Qué se debe hacer ante objetos sueltos que podrían caer?","options":[{"key":"a","text":"Asegurarlos o reportarlos"},{"key":"b","text":"Ignorarlos si son pequeños"},{"key":"c","text":"Empujarlos fuera del camino"},{"key":"d","text":"Esperar a que caigan"}],"correctOption":"a"},{"id":"lof_q06","question":"Una zona de presión contenida puede ser peligrosa porque:","options":[{"key":"a","text":"Puede liberar energía de forma repentina"},{"key":"b","text":"Siempre está fría"},{"key":"c","text":"No produce movimiento"},{"key":"d","text":"Elimina la necesidad de barreras"}],"correctOption":"a"},{"id":"lof_q07","question":"Si una tarea genera movimiento de equipos o cargas, debo:","options":[{"key":"a","text":"Ubicarme fuera del recorrido posible"},{"key":"b","text":"Acercarme para observar mejor"},{"key":"c","text":"Pasar rápidamente por debajo"},{"key":"d","text":"Confiar en que me verán"}],"correctOption":"a"},{"id":"lof_q08","question":"¿Cuál es una conducta segura cerca de equipos móviles?","options":[{"key":"a","text":"Mantener distancia, visibilidad y respetar rutas/barreras"},{"key":"b","text":"Caminar detrás sin avisar"},{"key":"c","text":"Usar auriculares para concentrarse"},{"key":"d","text":"Cruzar sin contacto visual"}],"correctOption":"a"},{"id":"lof_q09","question":"Una carga suspendida representa riesgo porque:","options":[{"key":"a","text":"Puede caer o moverse inesperadamente"},{"key":"b","text":"No genera peligro si está quieta"},{"key":"c","text":"Solo afecta al operador"},{"key":"d","text":"Siempre está asegurada"}],"correctOption":"a"},{"id":"lof_q10","question":"¿Qué debo hacer si veo a un compañero en la línea de fuego?","options":[{"key":"a","text":"Advertirlo y tomar acción para sacarlo del peligro"},{"key":"b","text":"Esperar a que termine"},{"key":"c","text":"No intervenir"},{"key":"d","text":"Continuar mi tarea"}],"correctOption":"a"},{"id":"lof_q11","question":"Las zonas de exclusión deben:","options":[{"key":"a","text":"Establecerse y respetarse"},{"key":"b","text":"Usarse solo si hay visitantes"},{"key":"c","text":"Retirarse durante maniobras"},{"key":"d","text":"Ignorarse si hay apuro"}],"correctOption":"a"},{"id":"lof_q12","question":"¿Cuál de estas situaciones requiere especial atención a línea de fuego?","options":[{"key":"a","text":"Izajes, movimiento de vehículos y trabajos con presión"},{"key":"b","text":"Lectura de procedimientos en oficina"},{"key":"c","text":"Carga de datos administrativos"},{"key":"d","text":"Reuniones sin equipos"}],"correctOption":"a"},{"id":"lof_q13","question":"¿Qué acción es insegura?","options":[{"key":"a","text":"Ingresar a un área delimitada sin autorización"},{"key":"b","text":"Respetar barreras"},{"key":"c","text":"Reportar objetos potencialmente caídos"},{"key":"d","text":"Mantenerse fuera del recorrido de una carga"}],"correctOption":"a"},{"id":"lof_q14","question":"La prevención de objetos caídos incluye:","options":[{"key":"a","text":"Asegurar herramientas y materiales"},{"key":"b","text":"Dejar herramientas sobre bordes"},{"key":"c","text":"Retirar redes o barreras"},{"key":"d","text":"Lanzar objetos al nivel inferior"}],"correctOption":"a"},{"id":"lof_q15","question":"La conducta correcta frente a línea de fuego es:","options":[{"key":"a","text":"Identificar el peligro, ubicarse fuera de la trayectoria y respetar barreras"},{"key":"b","text":"Acercarse para terminar antes"},{"key":"c","text":"Confiar en la experiencia del operador"},{"key":"d","text":"Ignorar objetos sueltos"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_mechanical_lifting','tr_mechanical_lifting','{"id":"test_mechanical_lifting","trainingId":"tr_mechanical_lifting","title":"Examen Izaje Mecánico Seguro","description":"Evaluación final del training Izaje Mecánico Seguro, alineada con la regla IOGP Life-Saving Rules: Safe Mechanical Lifting.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"sml_q01","question":"La regla de izaje mecánico seguro exige:","options":[{"key":"a","text":"Planificar la operación y controlar el área"},{"key":"b","text":"Levantar sin planificación si la carga parece liviana"},{"key":"c","text":"Caminar bajo la carga para guiarla"},{"key":"d","text":"Usar cualquier equipo disponible"}],"correctOption":"a"},{"id":"sml_q02","question":"Antes de un izaje, debe confirmarse que:","options":[{"key":"a","text":"Equipo y carga fueron inspeccionados y son aptos para el trabajo"},{"key":"b","text":"La maniobra será rápida"},{"key":"c","text":"No haya observadores"},{"key":"d","text":"La carga tenga buen aspecto"}],"correctOption":"a"},{"id":"sml_q03","question":"¿Quién debe operar equipos de izaje?","options":[{"key":"a","text":"Personal calificado/autorizado para usar ese equipo"},{"key":"b","text":"Cualquier trabajador con experiencia general"},{"key":"c","text":"La persona más cercana"},{"key":"d","text":"Quien tenga más fuerza"}],"correctOption":"a"},{"id":"sml_q04","question":"¿Qué se debe hacer con el área de izaje?","options":[{"key":"a","text":"Establecer y respetar barreras o zonas de exclusión"},{"key":"b","text":"Dejar paso libre bajo la carga"},{"key":"c","text":"Permitir circulación normal"},{"key":"d","text":"Retirar señalización"}],"correctOption":"a"},{"id":"sml_q05","question":"Nunca se debe:","options":[{"key":"a","text":"Caminar debajo de una carga suspendida"},{"key":"b","text":"Inspeccionar accesorios"},{"key":"c","text":"Planificar el izaje"},{"key":"d","text":"Usar señales acordadas"}],"correctOption":"a"},{"id":"sml_q06","question":"Una carga suspendida es peligrosa porque:","options":[{"key":"a","text":"Puede caer, balancearse o desplazarse inesperadamente"},{"key":"b","text":"Siempre permanece inmóvil"},{"key":"c","text":"No afecta a personas fuera del operador"},{"key":"d","text":"No requiere zona de exclusión"}],"correctOption":"a"},{"id":"sml_q07","question":"¿Qué debe verificarse en accesorios de izaje?","options":[{"key":"a","text":"Que estén en buen estado y sean adecuados para la carga"},{"key":"b","text":"Solo el color"},{"key":"c","text":"Solo la marca"},{"key":"d","text":"Que sean nuevos aunque no correspondan"}],"correctOption":"a"},{"id":"sml_q08","question":"La comunicación durante el izaje debe ser:","options":[{"key":"a","text":"Clara y acordada entre quienes participan"},{"key":"b","text":"Improvisada durante la maniobra"},{"key":"c","text":"Solo por gritos"},{"key":"d","text":"Innecesaria si hay experiencia"}],"correctOption":"a"},{"id":"sml_q09","question":"Si el plan de izaje no está claro, corresponde:","options":[{"key":"a","text":"Detenerse y aclararlo antes de comenzar"},{"key":"b","text":"Comenzar y corregir durante la maniobra"},{"key":"c","text":"Levantar menos peso sin avisar"},{"key":"d","text":"Pedir a cualquiera que guíe"}],"correctOption":"a"},{"id":"sml_q10","question":"¿Qué acción es insegura?","options":[{"key":"a","text":"Usar equipo que no fue inspeccionado"},{"key":"b","text":"Controlar el área"},{"key":"c","text":"Respetar barreras"},{"key":"d","text":"Operar solo si se está calificado"}],"correctOption":"a"},{"id":"sml_q11","question":"El control del área evita que:","options":[{"key":"a","text":"Personas ingresen a zonas donde podrían ser golpeadas por la carga"},{"key":"b","text":"La carga sea identificada"},{"key":"c","text":"El equipo sea revisado"},{"key":"d","text":"El permiso sea completado"}],"correctOption":"a"},{"id":"sml_q12","question":"Antes de levantar una carga, se debe conocer:","options":[{"key":"a","text":"Peso, centro de gravedad y método seguro de izaje según aplique"},{"key":"b","text":"Solo el destino final"},{"key":"c","text":"Solo quién pidió el trabajo"},{"key":"d","text":"La hora de finalización"}],"correctOption":"a"},{"id":"sml_q13","question":"Si una persona cruza la zona de exclusión durante un izaje, se debe:","options":[{"key":"a","text":"Detener o asegurar la maniobra hasta restablecer el control"},{"key":"b","text":"Continuar para no demorar"},{"key":"c","text":"Aumentar la velocidad"},{"key":"d","text":"Ignorarla si está lejos"}],"correctOption":"a"},{"id":"sml_q14","question":"¿Cuál es una práctica segura?","options":[{"key":"a","text":"Inspeccionar carga, equipo y accesorios antes de izar"},{"key":"b","text":"Ubicarse bajo la carga para verla mejor"},{"key":"c","text":"Usar accesorios dañados solo una vez"},{"key":"d","text":"Levantar sin señalero cuando hace falta"}],"correctOption":"a"},{"id":"sml_q15","question":"La conducta correcta en izaje mecánico es:","options":[{"key":"a","text":"Planificar, inspeccionar, operar por personal calificado y respetar exclusiones"},{"key":"b","text":"Confiar en que la grúa puede con todo"},{"key":"c","text":"Improvisar la maniobra"},{"key":"d","text":"Permitir paso bajo la carga"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_hot_work','tr_hot_work','{"id":"test_hot_work","trainingId":"tr_hot_work","title":"Examen Trabajo en Caliente","description":"Evaluación final del training Trabajo en Caliente, alineada con la regla IOGP Life-Saving Rules: Hot Work.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"hw_q01","question":"La regla de trabajo en caliente se enfoca en controlar:","options":[{"key":"a","text":"Materiales inflamables y fuentes de ignición"},{"key":"b","text":"Solo el ruido"},{"key":"c","text":"La documentación de viajes"},{"key":"d","text":"El orden de herramientas únicamente"}],"correctOption":"a"},{"id":"hw_q02","question":"Antes de iniciar un trabajo en caliente, se debe confirmar que:","options":[{"key":"a","text":"Los materiales inflamables fueron retirados o aislados"},{"key":"b","text":"La tarea será corta"},{"key":"c","text":"No hay necesidad de autorización"},{"key":"d","text":"El área está concurrida"}],"correctOption":"a"},{"id":"hw_q03","question":"¿Qué debe obtenerse antes de un trabajo en caliente cuando corresponde?","options":[{"key":"a","text":"Autorización o permiso de trabajo"},{"key":"b","text":"Una opinión informal"},{"key":"c","text":"Solo una herramienta nueva"},{"key":"d","text":"Una fotografía del área"}],"correctOption":"a"},{"id":"hw_q04","question":"En áreas peligrosas, antes de iniciar trabajo en caliente se debe confirmar:","options":[{"key":"a","text":"Prueba de gases completada y monitoreo según corresponda"},{"key":"b","text":"Que no haya viento"},{"key":"c","text":"Que el turno sea diurno"},{"key":"d","text":"Que haya poco personal"}],"correctOption":"a"},{"id":"hw_q05","question":"Una fuente de ignición puede ser:","options":[{"key":"a","text":"Chispas, llama abierta o superficies calientes"},{"key":"b","text":"Agua potable"},{"key":"c","text":"Señalización"},{"key":"d","text":"Documentos impresos"}],"correctOption":"a"},{"id":"hw_q06","question":"Si aparece material inflamable durante la tarea, se debe:","options":[{"key":"a","text":"Detener y controlar la condición antes de continuar"},{"key":"b","text":"Continuar si falta poco"},{"key":"c","text":"Cubrirlo con cualquier elemento"},{"key":"d","text":"Ignorarlo si no se incendió"}],"correctOption":"a"},{"id":"hw_q07","question":"El monitoreo de gases en trabajo en caliente sirve para:","options":[{"key":"a","text":"Detectar atmósferas inflamables durante la tarea"},{"key":"b","text":"Medir productividad"},{"key":"c","text":"Controlar la temperatura corporal"},{"key":"d","text":"Reemplazar el permiso"}],"correctOption":"a"},{"id":"hw_q08","question":"¿Cuál es una acción insegura?","options":[{"key":"a","text":"Soldar sin controlar inflamables"},{"key":"b","text":"Obtener autorización"},{"key":"c","text":"Retirar materiales combustibles"},{"key":"d","text":"Identificar fuentes de ignición"}],"correctOption":"a"},{"id":"hw_q09","question":"El control de inflamables puede incluir:","options":[{"key":"a","text":"Retirar, aislar o proteger materiales combustibles"},{"key":"b","text":"Acercarlos para vigilarlos"},{"key":"c","text":"Dejarlos si están ordenados"},{"key":"d","text":"Cubrirlos sin evaluación"}],"correctOption":"a"},{"id":"hw_q10","question":"¿Cuándo debe reevaluarse un trabajo en caliente?","options":[{"key":"a","text":"Si cambian las condiciones del área o del trabajo"},{"key":"b","text":"Solo al finalizar"},{"key":"c","text":"Nunca durante la tarea"},{"key":"d","text":"Cuando termina el turno siguiente"}],"correctOption":"a"},{"id":"hw_q11","question":"La autorización de trabajo en caliente ayuda a confirmar:","options":[{"key":"a","text":"Riesgos, controles y condiciones para realizar la tarea"},{"key":"b","text":"Que no se requieren controles"},{"key":"c","text":"Que se puede omitir el monitoreo"},{"key":"d","text":"Que la tarea no necesita supervisión"}],"correctOption":"a"},{"id":"hw_q12","question":"Antes de generar chispas o llama, se debe:","options":[{"key":"a","text":"Controlar fuentes de ignición y materiales inflamables"},{"key":"b","text":"Trabajar sin pausa"},{"key":"c","text":"Aumentar ventilación sin medir"},{"key":"d","text":"Retirar señalización"}],"correctOption":"a"},{"id":"hw_q13","question":"¿Qué significa controlar fuentes de ignición?","options":[{"key":"a","text":"Identificarlas y evitar que enciendan materiales o atmósferas inflamables"},{"key":"b","text":"Usarlas más cerca del material"},{"key":"c","text":"Apagarlas solo al final"},{"key":"d","text":"Ignorarlas si son pequeñas"}],"correctOption":"a"},{"id":"hw_q14","question":"Si la prueba de gases indica condición no segura, corresponde:","options":[{"key":"a","text":"No iniciar o detener el trabajo hasta controlar la condición"},{"key":"b","text":"Trabajar rápidamente"},{"key":"c","text":"Confiar en el olfato"},{"key":"d","text":"Usar menos herramientas"}],"correctOption":"a"},{"id":"hw_q15","question":"La conducta correcta en trabajo en caliente es:","options":[{"key":"a","text":"Obtener autorización, controlar inflamables/ignición y verificar atmósfera cuando aplique"},{"key":"b","text":"Soldar si hay experiencia"},{"key":"c","text":"Evitar el permiso para ahorrar tiempo"},{"key":"d","text":"Hacer el monitoreo solo después"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_work_authorization','tr_work_authorization','{"id":"test_work_authorization","trainingId":"tr_work_authorization","title":"Examen Autorización de Trabajo","description":"Evaluación final del training Autorización de Trabajo, alineada con la regla IOGP Life-Saving Rules: Work Authorisation.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"wa_q01","question":"La autorización de trabajo indica que una tarea debe realizarse:","options":[{"key":"a","text":"Con un permiso válido cuando sea requerido"},{"key":"b","text":"Solo con autorización verbal informal"},{"key":"c","text":"Sin revisar controles"},{"key":"d","text":"Según la rapidez necesaria"}],"correctOption":"a"},{"id":"wa_q02","question":"Antes de iniciar un trabajo autorizado, debo entender:","options":[{"key":"a","text":"Alcance, riesgos, controles y condiciones del permiso"},{"key":"b","text":"Solo quién firmó el documento"},{"key":"c","text":"Solo la duración estimada"},{"key":"d","text":"Solo el nombre de la empresa"}],"correctOption":"a"},{"id":"wa_q03","question":"Un permiso de trabajo válido ayuda a confirmar que:","options":[{"key":"a","text":"La tarea, los riesgos y los controles fueron revisados"},{"key":"b","text":"No existen riesgos"},{"key":"c","text":"No se necesita supervisión"},{"key":"d","text":"El trabajo puede hacerse de cualquier forma"}],"correctOption":"a"},{"id":"wa_q04","question":"Si el trabajo cambia respecto de lo autorizado, se debe:","options":[{"key":"a","text":"Detener y revisar/actualizar la autorización"},{"key":"b","text":"Continuar si parece seguro"},{"key":"c","text":"Terminar rápido"},{"key":"d","text":"Avisar al final"}],"correctOption":"a"},{"id":"wa_q05","question":"¿Qué debe hacer un trabajador si no entiende una condición del permiso?","options":[{"key":"a","text":"Pedir aclaración antes de comenzar"},{"key":"b","text":"Firmar igual"},{"key":"c","text":"Ignorar esa parte"},{"key":"d","text":"Dejar que otro decida"}],"correctOption":"a"},{"id":"wa_q06","question":"La autorización de trabajo es especialmente importante para:","options":[{"key":"a","text":"Tareas de alto riesgo o no rutinarias"},{"key":"b","text":"Cualquier pausa de descanso"},{"key":"c","text":"Tareas administrativas simples"},{"key":"d","text":"Reuniones sin trabajo operativo"}],"correctOption":"a"},{"id":"wa_q07","question":"¿Qué acción es insegura?","options":[{"key":"a","text":"Trabajar fuera del alcance del permiso"},{"key":"b","text":"Verificar controles"},{"key":"c","text":"Leer condiciones del permiso"},{"key":"d","text":"Confirmar que el permiso está vigente"}],"correctOption":"a"},{"id":"wa_q08","question":"Antes de iniciar, las personas involucradas deben:","options":[{"key":"a","text":"Conocer su rol y las condiciones de seguridad"},{"key":"b","text":"Confiar en que alguien más leyó el permiso"},{"key":"c","text":"Firmar sin participar"},{"key":"d","text":"Empezar mientras se completa el permiso"}],"correctOption":"a"},{"id":"wa_q09","question":"Un permiso vencido o inválido significa que:","options":[{"key":"a","text":"No debe usarse para ejecutar el trabajo"},{"key":"b","text":"Puede usarse si hay apuro"},{"key":"c","text":"Sirve hasta que alguien lo note"},{"key":"d","text":"Solo afecta a contratistas"}],"correctOption":"a"},{"id":"wa_q10","question":"¿Qué debe pasar con los controles definidos en el permiso?","options":[{"key":"a","text":"Deben implementarse antes y durante la tarea según corresponda"},{"key":"b","text":"Pueden quedar para después"},{"key":"c","text":"Son opcionales"},{"key":"d","text":"Solo se aplican si ocurre un incidente"}],"correctOption":"a"},{"id":"wa_q11","question":"La comunicación previa al trabajo sirve para:","options":[{"key":"a","text":"Alinear riesgos, controles, permisos y responsabilidades"},{"key":"b","text":"Evitar usar el permiso"},{"key":"c","text":"Reducir la cantidad de controles"},{"key":"d","text":"Acelerar sin revisar"}],"correctOption":"a"},{"id":"wa_q12","question":"Si las condiciones del área dejan de coincidir con el permiso, se debe:","options":[{"key":"a","text":"Parar y reevaluar"},{"key":"b","text":"Continuar hasta terminar"},{"key":"c","text":"Ignorar si la tarea empezó"},{"key":"d","text":"Cambiar la tarea sin avisar"}],"correctOption":"a"},{"id":"wa_q13","question":"¿Quién debe cumplir las condiciones del permiso?","options":[{"key":"a","text":"Todas las personas involucradas en el trabajo"},{"key":"b","text":"Solo quien lo emitió"},{"key":"c","text":"Solo el supervisor"},{"key":"d","text":"Solo visitantes"}],"correctOption":"a"},{"id":"wa_q14","question":"La autorización no reemplaza:","options":[{"key":"a","text":"La identificación de riesgos y aplicación de controles"},{"key":"b","text":"El apuro operativo"},{"key":"c","text":"La experiencia individual"},{"key":"d","text":"La decisión de trabajar solo"}],"correctOption":"a"},{"id":"wa_q15","question":"La conducta correcta es:","options":[{"key":"a","text":"Trabajar dentro del alcance autorizado y detenerse si cambian las condiciones"},{"key":"b","text":"Adaptar el permiso verbalmente sin registro"},{"key":"c","text":"Trabajar sin leer el permiso"},{"key":"d","text":"Cumplir solo las condiciones fáciles"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_bypass_controls','tr_bypass_controls','{"id":"test_bypass_controls","trainingId":"tr_bypass_controls","title":"Examen Bypass de Controles de Seguridad","description":"Evaluación final del training Bypass de Controles de Seguridad, alineada con la regla IOGP Life-Saving Rules: Bypassing Safety Controls.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"bsc_q01","question":"Antes de anular o deshabilitar un control de seguridad, se debe:","options":[{"key":"a","text":"Obtener autorización"},{"key":"b","text":"Hacerlo si molesta"},{"key":"c","text":"Avisar después"},{"key":"d","text":"Pedir ayuda informal"}],"correctOption":"a"},{"id":"bsc_q02","question":"Un control de seguridad puede ser:","options":[{"key":"a","text":"Un dispositivo, alarma, guarda, procedimiento o sistema crítico"},{"key":"b","text":"Solo un cartel decorativo"},{"key":"c","text":"Únicamente el uniforme"},{"key":"d","text":"Solo una herramienta manual"}],"correctOption":"a"},{"id":"bsc_q03","question":"Bypassing Safety Controls significa evitar:","options":[{"key":"a","text":"Anular controles sin autorización y sin controles alternativos"},{"key":"b","text":"Leer procedimientos"},{"key":"c","text":"Usar permisos"},{"key":"d","text":"Reportar condiciones inseguras"}],"correctOption":"a"},{"id":"bsc_q04","question":"Si un control de seguridad impide avanzar con una tarea, corresponde:","options":[{"key":"a","text":"Detenerse y gestionar autorización para cualquier bypass"},{"key":"b","text":"Desactivarlo temporalmente sin avisar"},{"key":"c","text":"Cubrir la alarma"},{"key":"d","text":"Pedir a otro que lo haga"}],"correctOption":"a"},{"id":"bsc_q05","question":"¿Qué debe existir si se autoriza un bypass?","options":[{"key":"a","text":"Controles alternativos adecuados y comunicados"},{"key":"b","text":"Solo una promesa verbal"},{"key":"c","text":"La intención de terminar rápido"},{"key":"d","text":"Ningún registro"}],"correctOption":"a"},{"id":"bsc_q06","question":"¿Cuál es una acción insegura?","options":[{"key":"a","text":"Retirar una guarda de máquina sin autorización"},{"key":"b","text":"Reportar un control dañado"},{"key":"c","text":"Cumplir una barrera"},{"key":"d","text":"Solicitar permiso para deshabilitar un sistema"}],"correctOption":"a"},{"id":"bsc_q07","question":"Si detecto un control de seguridad dañado o deshabilitado, debo:","options":[{"key":"a","text":"Reportarlo y no asumir que es seguro"},{"key":"b","text":"Ignorarlo si el equipo funciona"},{"key":"c","text":"Usarlo para avanzar más rápido"},{"key":"d","text":"Retirarlo por completo"}],"correctOption":"a"},{"id":"bsc_q08","question":"Los sistemas de seguridad críticos existen para:","options":[{"key":"a","text":"Prevenir eventos graves o reducir sus consecuencias"},{"key":"b","text":"Demorar el trabajo"},{"key":"c","text":"Reemplazar capacitación"},{"key":"d","text":"Evitar inspecciones"}],"correctOption":"a"},{"id":"bsc_q09","question":"La autorización para bypass debe dejar claro:","options":[{"key":"a","text":"Qué se deshabilita, por cuánto tiempo y qué controles alternativos aplican"},{"key":"b","text":"Solo quién está de turno"},{"key":"c","text":"Que el riesgo desapareció"},{"key":"d","text":"Que no hace falta comunicar"}],"correctOption":"a"},{"id":"bsc_q10","question":"¿Qué debe hacerse al terminar la necesidad del bypass?","options":[{"key":"a","text":"Restablecer el control de seguridad según procedimiento"},{"key":"b","text":"Dejarlo deshabilitado"},{"key":"c","text":"Olvidar el registro"},{"key":"d","text":"Tapar la señalización"}],"correctOption":"a"},{"id":"bsc_q11","question":"Una alarma deshabilitada sin autorización:","options":[{"key":"a","text":"Puede impedir detectar una condición peligrosa"},{"key":"b","text":"Siempre mejora el trabajo"},{"key":"c","text":"No cambia el riesgo"},{"key":"d","text":"Es aceptable si nadie la oye"}],"correctOption":"a"},{"id":"bsc_q12","question":"¿Quién debe conocer un bypass autorizado?","options":[{"key":"a","text":"Las personas afectadas por el cambio de control"},{"key":"b","text":"Solo quien lo ejecutó"},{"key":"c","text":"Nadie para evitar confusión"},{"key":"d","text":"Solo administración"}],"correctOption":"a"},{"id":"bsc_q13","question":"Los controles de seguridad no deben modificarse por:","options":[{"key":"a","text":"Comodidad, apuro o conveniencia sin autorización"},{"key":"b","text":"Procedimiento aprobado"},{"key":"c","text":"Evaluación de riesgos"},{"key":"d","text":"Plan autorizado"}],"correctOption":"a"},{"id":"bsc_q14","question":"Si no se aprueba el bypass, se debe:","options":[{"key":"a","text":"No realizar la tarea de esa forma"},{"key":"b","text":"Hacerlo igual con cuidado"},{"key":"c","text":"Desactivar otro control"},{"key":"d","text":"Continuar sin comunicar"}],"correctOption":"a"},{"id":"bsc_q15","question":"La conducta correcta ante controles de seguridad es:","options":[{"key":"a","text":"Respetarlos y obtener autorización antes de cualquier anulación o deshabilitación"},{"key":"b","text":"Adaptarlos libremente"},{"key":"c","text":"Desactivarlos si demoran"},{"key":"d","text":"Usarlos solo durante auditorías"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;
INSERT INTO public.training_test_authoritative_bank(test_id,training_id,test_definition) VALUES ('test_safe_driving','tr_safe_driving','{"id":"test_safe_driving","trainingId":"tr_safe_driving","title":"Examen Conducción Segura","description":"Evaluación final del training Conducción Segura, alineada con la regla IOGP Life-Saving Rules: Driving.","passingScore":80,"questionsPerAttempt":5,"maxAttempts":3,"attemptMode":"sequential_blocks","questions":[{"id":"drv_q01","question":"Una regla básica de conducción segura es:","options":[{"key":"a","text":"Usar siempre cinturón de seguridad"},{"key":"b","text":"Usar cinturón solo en ruta"},{"key":"c","text":"No usar cinturón en trayectos cortos"},{"key":"d","text":"Usar cinturón solo si hay controles"}],"correctOption":"a"},{"id":"drv_q02","question":"Respecto de la velocidad, se debe:","options":[{"key":"a","text":"No exceder límites y reducir velocidad según condiciones"},{"key":"b","text":"Mantener siempre la máxima permitida"},{"key":"c","text":"Acelerar para terminar antes"},{"key":"d","text":"Ignorar condiciones del camino"}],"correctOption":"a"},{"id":"drv_q03","question":"Durante la conducción, el uso de teléfonos o dispositivos debe:","options":[{"key":"a","text":"Evitarse si distrae o está prohibido por la regla/procedimiento"},{"key":"b","text":"Permitirse para ahorrar tiempo"},{"key":"c","text":"Hacerse solo en curvas"},{"key":"d","text":"Usarse si el mensaje es corto"}],"correctOption":"a"},{"id":"drv_q04","question":"Antes de conducir, el conductor debe estar:","options":[{"key":"a","text":"Apto, descansado y alerta"},{"key":"b","text":"Cansado pero apurado"},{"key":"c","text":"Somnoliento si el viaje es corto"},{"key":"d","text":"Distraído por llamadas"}],"correctOption":"a"},{"id":"drv_q05","question":"¿Qué debe hacerse ante malas condiciones del camino o clima?","options":[{"key":"a","text":"Reducir velocidad y adaptar la conducción"},{"key":"b","text":"Aumentar velocidad para salir antes"},{"key":"c","text":"Conducir igual"},{"key":"d","text":"Apagar luces para ahorrar batería"}],"correctOption":"a"},{"id":"drv_q06","question":"El cinturón de seguridad protege porque:","options":[{"key":"a","text":"Reduce el riesgo de lesiones graves en una colisión"},{"key":"b","text":"Evita revisar el vehículo"},{"key":"c","text":"Permite conducir más rápido"},{"key":"d","text":"Reemplaza la atención del conductor"}],"correctOption":"a"},{"id":"drv_q07","question":"¿Cuál es una acción insegura al conducir?","options":[{"key":"a","text":"Leer mensajes mientras se maneja"},{"key":"b","text":"Mantener distancia segura"},{"key":"c","text":"Respetar límites de velocidad"},{"key":"d","text":"Usar cinturón"}],"correctOption":"a"},{"id":"drv_q08","question":"La fatiga al conducir puede causar:","options":[{"key":"a","text":"Pérdida de atención y aumento del riesgo de accidente"},{"key":"b","text":"Mejor reacción"},{"key":"c","text":"Menor necesidad de descanso"},{"key":"d","text":"Mayor control del vehículo"}],"correctOption":"a"},{"id":"drv_q09","question":"La conducción segura requiere:","options":[{"key":"a","text":"Seguir reglas de tránsito y requisitos de la empresa"},{"key":"b","text":"Confiar solo en experiencia"},{"key":"c","text":"Ignorar rutas planificadas"},{"key":"d","text":"Usar el teléfono para mantenerse despierto"}],"correctOption":"a"},{"id":"drv_q10","question":"Antes de iniciar un viaje laboral, puede ser necesario confirmar:","options":[{"key":"a","text":"Condición del vehículo, ruta y aptitud del conductor"},{"key":"b","text":"Solo el horario de llegada"},{"key":"c","text":"Solo el color del vehículo"},{"key":"d","text":"Solo quién paga el combustible"}],"correctOption":"a"},{"id":"drv_q11","question":"Si el conductor no está en condiciones de manejar, debe:","options":[{"key":"a","text":"No conducir y reportar la situación"},{"key":"b","text":"Conducir más lento sin avisar"},{"key":"c","text":"Pedir café y continuar siempre"},{"key":"d","text":"Delegar el volante informalmente"}],"correctOption":"a"},{"id":"drv_q12","question":"El respeto de límites de velocidad aplica:","options":[{"key":"a","text":"En todos los trayectos y condiciones"},{"key":"b","text":"Solo cuando hay policía"},{"key":"c","text":"Solo en caminos urbanos"},{"key":"d","text":"Solo con pasajeros"}],"correctOption":"a"},{"id":"drv_q13","question":"Mantener atención al conducir implica:","options":[{"key":"a","text":"Evitar distracciones y concentrarse en el camino"},{"key":"b","text":"Revisar mensajes continuamente"},{"key":"c","text":"Comer y manejar con una mano siempre"},{"key":"d","text":"Mirar el celular en rectas"}],"correctOption":"a"},{"id":"drv_q14","question":"Una distancia segura ayuda a:","options":[{"key":"a","text":"Tener tiempo para reaccionar ante imprevistos"},{"key":"b","text":"Llegar antes"},{"key":"c","text":"Bloquear otros vehículos"},{"key":"d","text":"Evitar usar cinturón"}],"correctOption":"a"},{"id":"drv_q15","question":"La conducta correcta al conducir es:","options":[{"key":"a","text":"Usar cinturón, respetar velocidad, evitar distracciones y conducir apto"},{"key":"b","text":"Conducir rápido si hay experiencia"},{"key":"c","text":"Responder mensajes breves"},{"key":"d","text":"Ignorar fatiga en viajes cortos"}],"correctOption":"a"}]}'::jsonb) ON CONFLICT (test_id) DO UPDATE SET training_id = EXCLUDED.training_id, test_definition = EXCLUDED.test_definition;

CREATE OR REPLACE FUNCTION public.record_training_test_attempt_audited(p_assignment_id uuid, p_test jsonb, p_questions jsonb, p_answers jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
 v_assignment record; v_test_id text; v_training_id text; v_user_id uuid;
 v_test_hash text; v_version_id uuid; v_attempt_id uuid; v_audit_id uuid;
 v_number int; v_total int; v_correct int; v_score int; v_pass boolean;
 v_q jsonb; v_key text; v_selected text; v_answer_count int;
 v_canonical_test jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
 SELECT id, user_id, training_id::text AS training_id INTO v_assignment
 FROM public.training_assignments WHERE id=p_assignment_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Assignment not found'; END IF;
 -- The worker may use a profile id distinct from their Supabase auth user id.
 IF NOT EXISTS (SELECT 1 FROM public.profiles
   WHERE id=v_assignment.user_id
     AND (auth_user_id=auth.uid() OR id=auth.uid())
     AND status='active'
     AND deleted_at IS NULL
     AND tenant_id = (
       SELECT tenant_id FROM public.training_assignments WHERE id=p_assignment_id
     ))
 THEN RAISE EXCEPTION 'Assignment does not belong to an active authenticated worker'; END IF;
 v_user_id:=v_assignment.user_id;
 -- Verify caller-provided test definitions against a private, server-owned canonical bank.
 -- The client's correctOption, passingScore, and maxAttempts are NOT trusted.
 SELECT test_definition INTO v_canonical_test
 FROM public.training_test_authoritative_bank
 WHERE test_id = p_test->>'id' AND training_id = v_assignment.training_id::text;
 IF NOT FOUND OR p_test IS DISTINCT FROM v_canonical_test THEN
   RAISE EXCEPTION 'Exam definition does not match server-authoritative bank';
 END IF;
 IF jsonb_typeof(p_questions) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'Invalid question batch';
 END IF;
 -- Order of options can be shuffled by the UI. Each question must otherwise
 -- match the server-side content exactly, including its correct answer.
 IF EXISTS (
   SELECT 1 FROM jsonb_array_elements(p_questions) q
   LEFT JOIN LATERAL (
     SELECT b.value AS canonical
     FROM jsonb_array_elements(v_canonical_test->'questions') b
     WHERE b.value->>'id' = q.value->>'id'
     LIMIT 1
   ) b ON TRUE
   WHERE b.canonical IS NULL
      OR (q.value - 'options') IS DISTINCT FROM (b.canonical - 'options')
      OR (
        SELECT jsonb_agg(o.value ORDER BY o.value->>'key')
        FROM jsonb_array_elements(q.value->'options') o
      ) IS DISTINCT FROM (
        SELECT jsonb_agg(o.value ORDER BY o.value->>'key')
        FROM jsonb_array_elements(b.canonical->'options') o
      )
 ) THEN
   RAISE EXCEPTION 'Question batch differs from server-authoritative bank';
 END IF;

 v_training_id:=p_test->>'trainingId'; v_test_id:=p_test->>'id';
 IF v_training_id IS NULL OR v_training_id<>v_assignment.training_id OR v_test_id IS NULL THEN
   RAISE EXCEPTION 'Mismatched test/training';
 END IF;
 IF jsonb_typeof(p_test->'questions')<>'array' OR jsonb_typeof(p_questions)<>'array' OR jsonb_typeof(p_answers)<>'object' THEN
   RAISE EXCEPTION 'Invalid test payload'; END IF;
 v_total:=jsonb_array_length(p_questions);
 IF v_total=0 OR v_total<>coalesce((p_test->>'questionsPerAttempt')::int,0) THEN RAISE EXCEPTION 'Invalid question count'; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(p_questions) q WHERE NOT EXISTS
     (SELECT 1 FROM jsonb_array_elements(p_test->'questions') full_q WHERE full_q->>'id'=q->>'id'))>0
 THEN RAISE EXCEPTION 'Question outside test bank'; END IF;
 SELECT count(*) INTO v_number FROM public.training_test_attempts
   WHERE assignment_id=p_assignment_id AND test_id=v_test_id;
 IF EXISTS (SELECT 1 FROM public.training_test_attempts WHERE assignment_id=p_assignment_id AND test_id=v_test_id AND passed) THEN
   RAISE EXCEPTION 'Exam already approved'; END IF;
 v_number:=v_number+1;
 IF v_number>coalesce((p_test->>'maxAttempts')::int,0) THEN RAISE EXCEPTION 'Maximum attempts reached'; END IF;
 -- Enforce correct sequential block even across reloads.
 IF (SELECT count(*) FROM jsonb_array_elements(p_questions) q WHERE NOT EXISTS
    (SELECT 1 FROM jsonb_array_elements(p_test->'questions') WITH ORDINALITY bank(question,ord)
       WHERE bank.question->>'id'=q->>'id'
       AND bank.ord BETWEEN (v_number-1)*v_total+1 AND v_number*v_total))>0
 THEN RAISE EXCEPTION 'Incorrect question batch'; END IF;
 v_answer_count:=0; v_correct:=0;
 FOR v_q IN SELECT value FROM jsonb_array_elements(p_questions) LOOP
   v_key:=v_q->>'id'; v_selected:=p_answers->>v_key;
   IF v_selected IS NULL OR NOT EXISTS
      (SELECT 1 FROM jsonb_array_elements(v_q->'options') opt WHERE opt->>'key'=v_selected)
   THEN RAISE EXCEPTION 'Incomplete/invalid answer for question %', v_key; END IF;
   v_answer_count:=v_answer_count+1;
   IF v_selected=v_q->>'correctOption' THEN v_correct:=v_correct+1; END IF;
 END LOOP;
 v_score:=round(100.0*v_correct/v_total);
 v_pass:=v_score>=coalesce((p_test->>'passingScore')::int,100);
 v_test_hash:=encode(digest(p_test::text,'sha256'),'hex');
 INSERT INTO public.training_test_audit_versions(test_id,training_id,content_hash,snapshot)
 VALUES(v_test_id,v_training_id,v_test_hash,p_test)
 ON CONFLICT (test_id,content_hash) DO NOTHING;
 SELECT id INTO v_version_id FROM public.training_test_audit_versions
 WHERE test_id=v_test_id AND content_hash=v_test_hash;
 INSERT INTO public.training_test_attempts(assignment_id,user_id,training_id,test_id,attempt_number,score,correct_answers,total_questions,passed)
 VALUES(p_assignment_id,v_user_id,v_training_id,v_test_id,v_number,v_score,v_correct,v_total,v_pass)
 RETURNING id INTO v_attempt_id;
 INSERT INTO public.training_test_audit_attempts(attempt_id,version_id,assignment_id,user_id,attempt_number,snapshot)
 VALUES(v_attempt_id,v_version_id,p_assignment_id,v_user_id,v_number,p_questions)
 RETURNING id INTO v_audit_id;
 INSERT INTO public.training_test_attempt_answers(attempt_id,question_id,selected_option,correct_option,is_correct)
 SELECT v_attempt_id, q->>'id',p_answers->>(q->>'id'),q->>'correctOption',
    (p_answers->>(q->>'id'))=(q->>'correctOption') FROM jsonb_array_elements(p_questions) q;
 INSERT INTO public.training_test_audit_answers(audit_attempt_id,question_id,question_text,options_snapshot,selected_option,correct_option,is_correct,question_order)
 SELECT v_audit_id,q->>'id',q->>'question',q->'options',p_answers->>(q->>'id'),q->>'correctOption',
   (p_answers->>(q->>'id'))=(q->>'correctOption'),ord::int
 FROM jsonb_array_elements(p_questions) WITH ORDINALITY AS t(q,ord);
 RETURN v_attempt_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.record_training_test_attempt_audited(uuid,jsonb,jsonb,jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_training_test_attempt_audited(uuid,jsonb,jsonb,jsonb) TO authenticated;
COMMIT;
